/* ============ MY EVC — Espace étudiant ============ */
const fname = f => S.formations[f].name;
const dateOf = x => addDays(x.d, x.h);
const monthShort = d => d.toLocaleDateString('fr-FR',{month:'short'}).replace('.','');
const datebox = (d, f) => `<div class="datebox ${f?'c-'+f:''}"><span>${monthShort(d)}</span><b>${d.getDate()}</b></div>`;
const statusPill = s => pill(STATUS[s][0], STATUS[s][1]);
function seanceRow(x, act=true){
  const d = dateOf(x), virt = x.mode==='Virtuel';
  return `<div class="row-item clickable" data-act="seance" data-id="${x.id}">${datebox(d,x.f)}<div class="ri-main"><div class="ri-t">${esc(x.t)}</div><div class="ri-s">${fchip(x.f)} Séance ${x.n||''} · ${fmtD(d,{weekday:'long'})} · ${hrs(x)} · <i class="fa-solid ${virt?'fa-video':'fa-location-dot'}"></i> ${virt?'En ligne':'Présentiel'}</div></div>${act && x.d===0 && virt ? `<span class="btn btn-primary btn-sm">Rejoindre</span>` : `<i class="fa-solid fa-chevron-right muted"></i>`}</div>`;
}
function todoRow(t){
  const late = t.due<0 && ['afaire','encours','reprendre'].includes(t.status);
  return `<div class="row-item clickable c-${t.f}" data-act="todo" data-id="${t.id}"><span class="icon-sq"><i class="fa-solid ${t.f==='DG'?'fa-palette':t.f==='CM'?'fa-users':'fa-gears'}"></i></span><div class="ri-main"><div class="ri-t">${esc(t.t)}</div><div class="ri-s"${late?' style="color:var(--bad)"':''}>${t.status==='valide'?'Validé':late?'En retard':'À rendre '+relDay(t.due).toLowerCase()}</div></div>${statusPill(t.status)}</div>`;
}

/* ----- Tableau de bord : l'essentiel, dans l'ordre où l'étudiant en a besoin ----- */
const statBox = (label, value, sub='', cls='') => `<div class="stat ${cls}"><div class="s-l">${label}</div><div class="s-v">${value}</div>${sub?`<div class="s-s">${sub}</div>`:''}</div>`;
const actionRow = (icon, f, title, sub, btn) => `<div class="row-item next-row ${f?'c-'+f:''}"><span class="icon-sq"><i class="fa-solid ${icon}"></i></span><div class="ri-main"><div class="ri-t">${title}</div><div class="ri-s">${sub}</div></div>${btn}</div>`;
view('e-dashboard','etu','Accueil','fa-house-chimney', () => {
  const st = S.st, s = st.student, ps = payState(), fs = vf();
  const done = fs.reduce((a,f)=>a+F[f].sessions.done,0), total = fs.reduce((a,f)=>a+F[f].sessions.total,0);
  const pres = Math.round(fs.reduce((a,f)=>a+F[f].presence,0)/fs.length);
  const open = st.todos.filter(t=>fs.includes(t.f) && ['afaire','encours','reprendre'].includes(t.status));
  const next = st.seances.filter(x=>fs.includes(x.f) && x.d>=0).sort((a,b)=>a.d-b.d||a.h-b.h);
  const urgent = open.filter(t=>t.status!=='afaire').slice().sort((a,b)=>(b.status==='reprendre')-(a.status==='reprendre') || a.due-b.due);
  const todo = [];
  const sNow = next[0];
  if (sNow) { const virt = sNow.mode==='Virtuel'; todo.push(actionRow(virt?'fa-video':'fa-location-dot', sNow.f, esc(sNow.t), `Séance ${sNow.n} · ${relDay(sNow.d)} · ${hrs(sNow)} · ${virt?'En ligne':'Présentiel'}`, sNow.d===0&&virt?`<button class="btn btn-primary btn-sm" data-act="seance" data-id="${sNow.id}">Rejoindre</button>`:`<button class="btn btn-ghost btn-sm" data-act="seance" data-id="${sNow.id}">Détails</button>`)); }
  st.todos.filter(t=>fs.includes(t.f) && t.status==='afaire').slice(0,1).forEach(t => todo.push(actionRow('fa-play', t.f, esc(t.t), 'Nouveau projet · lisez les consignes et démarrez', `<button class="btn btn-ghost btn-sm" data-act="todo" data-id="${t.id}">Voir</button>`)));
  const watch = S.videos.find(v=>fs.includes(v.f) && v.pub && (st.tv.prog[v.id]||0)>0 && st.tv.prog[v.id]<1);
  if (watch) todo.push(actionRow('fa-play', watch.f, esc(watch.t), `Web TV · ${Math.round(st.tv.prog[watch.id]*100)} % regardé`, `<button class="btn btn-ghost btn-sm" data-act="tv-resume" data-id="${watch.id}">Reprendre</button>`));
  urgent.slice(0,2).forEach(t => todo.push(actionRow(t.status==='reprendre'?'fa-rotate-left':'fa-pen', t.f, esc(t.t), `${t.status==='reprendre'?'<b style="color:var(--bad)">À reprendre</b> · ':''}${t.due<0?'en retard':'à rendre '+relDay(t.due).toLowerCase()}`, `<button class="btn btn-ghost btn-sm" data-act="todo" data-id="${t.id}">Ouvrir</button>`)));
  if (ps.next) todo.push(actionRow('fa-wallet', null, `${fcfa(ps.next.amount-ps.next.paid)} à régler`, `${esc(ps.next.label)} · avant le ${ps.next.due}`, `<button class="btn btn-ghost btn-sm" data-act="pay">Payer</button>`));
  return `
  ${commBanner()}${onbCard()}<section class="hero-indigo">${motif('hero-motif')}
    <div class="hi-top"><div><div class="hi-kicker">Bonjour,</div><h2>${esc(s.first)} ${esc(s.last)}</h2><p>${todo.length ? `${todo.length} chose${todo.length>1?'s':''} à faire en priorité aujourd'hui.` : 'Tout est à jour. Bon travail !'}</p></div><div class="hi-meta"><span class="mono">${s.matricule}</span><span class="d-flex gap-1">${fs.map(fchip).join('')}</span></div></div>
    <div class="traj"><div class="traj-h"><b>Ma trajectoire</b><span>${fs.length>1?`${fs.length} formations`:esc(fname(fs[0]))}</span></div>${frise([{l:'Préinscription',s:'validée'},{l:'Formation',s:`${Math.round(fs.reduce((a,f)=>a+prog(f),0)/fs.length)} % · ${done} / ${total} séances`},{l:'Évaluations',s:'en cours'},{l:'Certification',s:'prévue en mars 2027'}], 1)}</div>
  </section>
  <div class="stats">${statBox('Présence', fmtPct(pres), `${done} / ${total} séances`)}${statBox('Travaux en cours', open.length, open.some(t=>t.status==='reprendre')?`${open.filter(t=>t.status==='reprendre').length} à reprendre`:'aucun à reprendre')}${statBox('Progression', fmtPct(fs.reduce((a,f)=>a+prog(f),0)/fs.length), fs.length>1?`${fs.length} formations`:esc(fname(fs[0])))}${statBox('Reste à payer', fcfa(ps.balance).replace(' FCFA','<small> FCFA</small>'), ps.next?`prochaine échéance ${ps.next.due}`:'formation soldée')}</div>
  <div class="grid g-2x">
    ${panel('À faire maintenant', todo.join('') || empty('Rien d\'urgent','fa-circle-check'), {p0:true})}
    ${panel('Prochaines séances', next.length ? next.slice(0,3).map(x=>seanceRow(x,false)).join('') : empty('Aucune séance programmée'), {p0:true, tools:`<a class="btn btn-ghost btn-sm" href="#e-seances">Emploi du temps</a>`})}
    ${panel(fs.length>1?'Mes formations':'Ma formation', fs.map(f=>`<div class="row-item clickable c-${f}" data-act="open-f" data-f="${f}"><div class="prog-row w-100"><div class="ri-main"><div class="ri-t">${esc(fname(f))}</div><div class="ri-s">${F[f].months} mois · ${chaptersDone(f)} / ${chapters(f)} séances</div></div>${bar(prog(f),f)}<span class="pct">${prog(f)}%</span></div></div>`).join(''), {p0:true, cls:'span-2', tools:`<a class="btn btn-ghost btn-sm" href="#e-formations">Détails</a>`})}
  </div>`;
}, () => { if (!S.st.onb.hidden && !S.st.onb.tourSeen) { S.st.onb.tourSeen = true; setTimeout(()=>{ if (S.view==='e-dashboard') tourStart(); }, 900); } });
ACT['open-f'] = el => { S.ui.ftab = el.dataset.f; go('e-formations'); };

/* ----- Mon profil ----- */
view('e-profil','etu','Mon profil','fa-id-card', () => { const s = S.st.student;
  return `<div class="mx-auto d-flex flex-column gap-3" style="max-width:720px">
  <section class="panel panel-b d-flex gap-3 align-items-center flex-wrap">
    <div class="position-relative">${avatar(s.first+' '+s.last,'lg',S.st.photo)}<label class="btn btn-primary btn-icon position-absolute rounded-circle" style="right:-4px;bottom:-4px;width:30px;height:30px" for="ph-in" title="Modifier la photo"><i class="fa-solid fa-camera"></i></label><input type="file" id="ph-in" accept="image/*" hidden data-chg="photo"></div>
    <div style="flex:1;min-width:200px"><h2 class="h4 mb-0">${esc(s.first)} ${esc(s.last)}</h2><div class="mono muted small">${s.matricule}</div><div class="d-flex gap-1 mt-2 flex-wrap">${fl().map(fchip).join('')}${pill(s.status,'ok')}</div></div>
    <div class="small text-sm-end"><div class="muted">${esc(s.session)}</div><div class="muted">Inscrit(e) le ${s.since}</div></div>
  </section>
  <section class="panel"><div class="panel-h"><h2>Coordonnées</h2></div><form data-submit="save-contact" class="panel-b row g-3" novalidate>
    <div class="col-sm-6"><label class="form-label" for="pc-mail">Email</label><input class="form-control" type="email" id="pc-mail" value="${esc(s.email)}" required><div class="invalid-feedback">Email invalide.</div></div>
    <div class="col-sm-6"><label class="form-label" for="pc-tel">Téléphone (WhatsApp)</label><input class="form-control" id="pc-tel" value="${esc(s.phone)}" required></div>
    <div class="col-sm-8"><label class="form-label" for="pc-city">Ville / commune</label><input class="form-control" id="pc-city" value="${esc(s.city)}"></div>
    <div class="col-sm-4 d-flex align-items-end"><button class="btn btn-primary w-100" type="submit">Enregistrer</button></div>
    <div class="col-12 small muted"><i class="fa-solid fa-lock me-1"></i>Nom, date de naissance (${s.birth}), formations et session sont gérés par l'administration.</div>
  </form></section>
  <section class="panel">
    <div class="row-item"><i class="fa-solid fa-key muted"></i><div class="ri-main"><div class="ri-t small">Mot de passe</div><div class="ri-s">Modifié le ${s.since}</div></div><button class="btn btn-ghost btn-sm" data-bs-toggle="collapse" data-bs-target="#pw-box" aria-expanded="false">Modifier</button></div>
    <div class="collapse" id="pw-box"><form data-submit="pwd" class="row g-2 px-3 pb-3" novalidate><div class="col-md-4"><input class="form-control" type="password" id="pw-old" placeholder="Actuel" required aria-label="Mot de passe actuel"></div><div class="col-md-4"><input class="form-control" type="password" id="pw-new" minlength="8" placeholder="Nouveau" required aria-label="Nouveau mot de passe"><div class="invalid-feedback">8 caractères minimum.</div></div><div class="col-md-4"><input class="form-control" type="password" id="pw-cf" placeholder="Confirmation" required aria-label="Confirmation"><div class="invalid-feedback" id="pw-cf-msg">Confirmez le mot de passe.</div></div><div class="col-12 text-end"><button class="btn btn-primary btn-sm" type="submit">Mettre à jour</button></div></form></div>
    ${[["Attestation d'inscription",'fa-file-pdf','fake-dl'],['Carte étudiant numérique','fa-id-badge','carte-etu'],['Historique académique','fa-clock-rotate-left','histo'],['Reçus et factures','fa-receipt','go-pay']].map(d=>`<div class="row-item clickable" data-act="${d[2]}" data-n="${d[0]}"><i class="fa-solid ${d[1]} muted"></i><div class="ri-main small">${d[0]}</div><i class="fa-solid fa-chevron-right muted small"></i></div>`).join('')}
  </section>
  <p class="small muted text-center mb-0">Compétences, expériences et liens professionnels se gèrent dans <a href="#e-cv">CV et portfolio</a>.</p>
  </div>`; });
ACT.histo = () => openModal({title:'Historique académique', body:`<ul class="timeline mb-0">${[['ok','Préinscription validée','01/10/2026'],['ok','Inscription et attribution du matricule',S.st.student.since],...fl().map(f=>['cur',`${fname(f)} en cours`,`${prog(f)} % réalisé`]),['','Certification prévue','Mars 2027']].map(t=>`<li class="${t[0]}"><span class="tdot"></span><b class="small d-block">${t[1]}</b><span class="small muted">${t[2]}</span></li>`).join('')}</ul>`});
ACT['go-pay'] = () => go('e-paiements');
/* Carte étudiant selon la charte : recto indigo avec le logo négatif, verso blanc avec QR code */
ACT['carte-etu'] = () => { const s = S.st.student, name = `${s.first} ${s.last}`;
  openModal({title:'Carte étudiant numérique', size:'modal-lg', body:`<div class="id-cards"><div class="id-card id-recto">${motif('id-motif')}<div class="d-flex justify-content-between align-items-start">${logoH('negatif','id-logo')}<span class="id-k">Carte étudiant</span></div><div class="d-flex gap-3 align-items-end mt-auto">${avatar(name,'id-ph',S.st.photo)}<div style="min-width:0"><b class="id-n">${esc(name)}</b><div class="id-f">${fl().map(f=>esc(fname(f))).join(' · ')}</div><div class="id-row"><span><small>N° étudiant</small>${s.matricule}</span><span><small>Validité</small>2026 – 2027</span></div></div></div></div>
  <div class="id-card id-verso"><div class="d-flex justify-content-between align-items-start">${logoSym('couleur','id-sym')}<div class="text-end small"><div class="muted">Session</div><b>${esc(s.session)}</b></div></div><p class="small muted mb-0 mt-3">Cette carte est personnelle. Elle donne accès aux salles de l'EVC et aux séances en présentiel. En cas de perte, prévenez la scolarité.</p><div class="d-flex justify-content-between align-items-end mt-auto"><div class="small"><div class="muted">${BRAND.tagline}</div><b>Bloom Square Akwaba, Palmeraie</b></div>${qrSVG('EVC-CARD-'+s.matricule,70)}</div></div></div>`,
  foot:`<button class="btn btn-ghost" data-act="fake-dl" data-n="Carte étudiant ${esc(s.matricule)} (Wallet)">Ajouter au téléphone</button><button class="btn btn-primary" data-act="fake-dl" data-n="Carte étudiant ${esc(s.matricule)}.pdf"><i class="fa-solid fa-download me-1"></i>Télécharger</button>`}); };
INP.photo = el => { const f = el.files[0]; if(!f) return; const r = new FileReader(); r.onload = () => { S.st.photo = r.result; rerender(); toast('Photo de profil mise à jour.'); }; r.readAsDataURL(f); };
ACT['save-contact'] = () => { const s=S.st.student; s.email=$('#pc-mail').value; s.phone=$('#pc-tel').value; s.city=$('#pc-city').value; toast('Coordonnées enregistrées.'); };
ACT['sk-add'] = () => { S.st.student.skills.push($('#sk-in').value.trim()); rerender(); };
ACT['sk-del'] = el => { S.st.student.skills.splice(+el.dataset.i,1); rerender(); };
ACT['save-links'] = () => { Object.assign(S.st.student.links,{linkedin:$('#ln-li').value,behance:$('#ln-be').value,site:$('#ln-si').value}); rerender(); toast('Liens enregistrés.'); };
ACT['exp-add'] = () => { S.st.student.exp.unshift({t:$('#ex-t').value,o:$('#ex-o').value,d:$('#ex-d').value||'2026'}); rerender(); toast('Expérience ajoutée.'); };
ACT['exp-del'] = el => { S.st.student.exp.splice(+el.dataset.i,1); rerender(); };
ACT.pwd = f => { if ($('#pw-new').value !== $('#pw-cf').value) { $('#pw-cf').setCustomValidity('x'); $('#pw-cf-msg').textContent='Les deux mots de passe ne correspondent pas.'; f.classList.add('was-validated'); $('#pw-cf').addEventListener('input',()=>$('#pw-cf').setCustomValidity(''),{once:true}); return; } f.reset(); f.classList.remove('was-validated'); toast('Mot de passe modifié. Les autres sessions ont été déconnectées.'); };

/* ----- Mes formations ----- */
view('e-formations','etu','Mes formations','fa-layer-group', () => {
  const fs = vf(); if (!fs.includes(S.ui.ftab)) S.ui.ftab = fs[0]; const f = S.ui.ftab, Fx = S.formations[f];
  const nextS = S.st.seances.filter(x=>x.f===f && x.d>=0).sort((a,b)=>a.d-b.d).slice(0,3);
  const lib = S.st.library.filter(l=>l.f===f).slice(0,4); const todos = S.st.todos.filter(t=>t.f===f); const evs = S.st.evals.filter(e=>e.f===f);
  return `${fs.length>1?`<ul class="nav nav-tabs mb-3">${fs.map(x=>`<li class="nav-item"><button class="nav-link ${x===f?'active':''}" data-act="ftab" data-f="${x}">${fchip(x)} <span class="ms-1">${fname(x)}</span></button></li>`).join('')}</ul>`:''}
  <div class="row g-3 c-${f}">
    <div class="col-xl-8 d-flex flex-column gap-3">
      <section class="panel"><div class="panel-b d-flex gap-3 flex-wrap"><span class="icon-sq" style="width:56px;height:56px;font-size:1.4rem"><i class="fa-solid ${Fx.icon}"></i></span><div style="flex:1;min-width:220px"><span class="small-caps">Présentation du programme</span><h2 class="h4 my-1">${Fx.name}</h2><p class="mb-2">${Fx.pitch}</p><div class="small muted"><i class="fa-regular fa-calendar me-1"></i>${Fx.months} mois · ${Fx.prog.length} séances · ${esc(Fx.format)}</div><div class="small muted"><i class="fa-solid fa-location-dot me-1"></i>${esc(Fx.place)} · Formateurs : ${Fx.trainer}, ${Fx.trainer2}</div></div></div>
        <div class="panel-b pt-0"><span class="small-caps">Objectifs pédagogiques</span><ul class="mt-2 mb-0 ps-3">${Fx.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></div></section>
      ${panel('Programme des séances', `<div class="prog-list">${Fx.prog.map(x=>{ const cur = !x.done && Fx.prog.find(y=>!y.done)===x, st = S.st.seances.find(y=>y.f===f && y.n===x.n), v = S.videos.find(y=>y.f===f && y.n===x.n && y.pub);
        return `<div class="prog-item ${x.done?'done':''} ${cur?'cur':''}" ${st?`data-act="seance" data-id="${st.id}" role="button" tabindex="0"`:''}><span class="pn">${x.done?'<i class="fa-solid fa-check"></i>':x.n}</span><div class="ri-main"><div class="small muted">Séance ${x.n} · ${fmtD(addDays(x.d),{weekday:'short',day:'numeric',month:'short'})} · ${x.hl}</div><div class="fw-semibold">${esc(x.t)}</div></div>${modePill(x.mode)}${x.done ? (v?`<button class="btn btn-ghost btn-sm" data-act="tv-resume" data-id="${v.id}"><i class="fa-solid fa-play me-1"></i>Revoir</button>`:'') : cur ? pill(x.d===0?"Aujourd'hui":'Prochaine','acc') : ''}</div>`; }).join('')}</div>`, {sub:`${chaptersDone(f)} séances réalisées sur ${chapters(f)} · format atelier pratique`, p0:true})}
      ${panel('Dates clés', `<div class="grid g-3 mb-3">${[['Première séance',fmtD(addDays(Fx.prog[0].d),{day:'2-digit',month:'2-digit',year:'numeric'}),'fa-flag'],['Prochaine séance',(n=>n?fmtD(addDays(n.d),{day:'2-digit',month:'2-digit',year:'numeric'}):'—')(Fx.prog.find(y=>!y.done)),'fa-calendar-day'],['Dernière séance',fmtD(addDays(Fx.prog[Fx.prog.length-1].d),{day:'2-digit',month:'2-digit',year:'numeric'}),'fa-flag-checkered']].map(x=>`<div class="d-flex gap-2 align-items-center"><span class="icon-sq"><i class="fa-solid ${x[2]}"></i></span><div><div class="small muted">${x[0]}</div><b>${x[1]}</b></div></div>`).join('')}</div>${nextS.map(x=>seanceRow(x)).join('')||empty('Aucune séance à venir')}`, {tools:`<a class="btn btn-ghost btn-sm" href="#e-seances">Emploi du temps</a>`})}
    </div>
    <div class="col-xl-4 d-flex flex-column gap-3">
      <section class="fcard c-${f}"><span class="small-caps">Progression individuelle</span><div class="d-flex align-items-end gap-2"><span class="big-pct">${prog(f)}%</span><span class="muted small mb-1">du programme</span></div>${bar(prog(f),f)}<div class="stat-line"><span>Présence</span><b>${Fx.presence} %</b></div><div class="stat-line"><span>Travaux validés</span><b>${todos.filter(t=>t.status==='valide').length} / ${todos.length}</b></div><div class="stat-line"><span>Moyenne</span><b>${avgF(f)??'—'} / 20</b></div></section>
      ${panel('Supports de cours', lib.map(l=>`<div class="row-item"><span class="lib-card p-0 border-0"><span class="ft t-${l.type}" style="width:30px;height:34px;font-size:.8rem"><i class="fa-solid ${typeIcon(l.type)}"></i></span></span><div class="ri-main"><div class="ri-t small">${esc(l.t)}</div><div class="ri-s">${l.size}</div></div><button class="btn btn-ghost btn-sm" data-act="fake-dl" data-n="${esc(l.t)}"><i class="fa-solid fa-download"></i></button></div>`).join(''), {p0:true, tools:`<a class="btn btn-ghost btn-sm" href="#e-bibliotheque">Bibliothèque</a>`})}
      ${panel('Travaux et projets', `<div class="d-flex flex-column gap-2">${Object.keys(STATUS).map(k=>{ const n=todos.filter(t=>t.status===k).length; return n?`<div class="stat-line"><span>${statusPill(k)}</span><b>${n}</b></div>`:''; }).join('')}<div class="d-flex gap-2 mt-2 flex-wrap"><a class="btn btn-ghost btn-sm" href="#e-todo">My To-Do</a><a class="btn btn-ghost btn-sm" href="#e-projets">Projets</a></div></div>`)}
      ${panel('Évaluations et résultats', evs.map(e=>`<div class="stat-line py-1"><span>${esc(e.t)}</span>${e.note!=null?uAppPill(e.note):'<b>—</b>'}</div>`).join(''))}
      ${panel('Conditions de certification', certCriteria(f).map(c=>`<div class="d-flex gap-2 align-items-center py-1 small"><span class="ci ${c.s} crit p-0 border-0" style="width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:.6rem"><i class="fa-solid ${c.s==='ok'?'fa-check':c.s==='ko'?'fa-xmark':'fa-hourglass-half'}"></i></span>${c.t}</div>`).join(''), {tools:`<a class="btn btn-ghost btn-sm" href="#e-certification">Dossier</a>`})}
    </div></div>`;
});
ACT.ftab = el => { S.ui.ftab = el.dataset.f; rerender(); };
const typeIcon = t => ({pdf:'fa-file-pdf',doc:'fa-file-word',xls:'fa-file-excel',ppt:'fa-file-powerpoint',vid:'fa-play',tuto:'fa-graduation-cap',zip:'fa-file-zipper'})[t];

/* ----- Mes séances ----- */
view('e-seances','etu','Mes séances','fa-calendar-days', () => {
  const tab = S.ui.stab || 'planning', fs = vf(), all = S.st.seances.filter(x=>fs.includes(x.f));
  const tabs = [['planning','Emploi du temps'],['next','Prochaines séances'],['pres','Présences'],['ratt','Rattrapages'],['replay','Replays']];
  let body = '';
  if (tab==='planning') { const wk = S.ui.week||0, mon = -3 + wk*7;
    body = `<div class="d-flex align-items-center gap-2 mb-3 flex-wrap"><button class="btn btn-ghost btn-sm btn-icon" data-act="week" data-w="-1" aria-label="Semaine précédente"><i class="fa-solid fa-chevron-left"></i></button><b>Semaine du ${fmtD(addDays(mon),{day:'numeric',month:'long'})} au ${fmtD(addDays(mon+5),{day:'numeric',month:'long'})}</b><button class="btn btn-ghost btn-sm btn-icon" data-act="week" data-w="1" aria-label="Semaine suivante"><i class="fa-solid fa-chevron-right"></i></button>${wk?`<button class="btn btn-ghost btn-sm" data-act="week" data-w="0">Cette semaine</button>`:''}<span class="ms-auto legend">${fs.map(f=>`<span><i style="background:var(--${f.toLowerCase()})"></i>${fname(f)}</span>`).join('')}</span></div>
    <div class="tbl"><div class="week">${[0,1,2,3,4,5].map(i=>{ const d = addDays(mon+i), ev = all.filter(x=>x.d===mon+i).sort((a,b)=>a.h-b.h);
      return `<div class="day ${mon+i===0?'today':''}"><div class="day-h"><span class="small-caps">${fmtD(d,{weekday:'short'})}</span><b>${d.getDate()}</b></div><div class="day-b">${ev.map(x=>`<div class="ev c-${x.f}" data-act="seance" data-id="${x.id}" role="button" tabindex="0"><b>${esc(x.t)}</b><span>Séance ${x.n} · ${hrs(x)} · ${modeLbl(x.mode)}</span></div>`).join('')||'<span class="small muted p-1">—</span>'}</div></div>`; }).join('')}</div></div>`; }
  if (tab==='next') body = `<div class="panel">${all.filter(x=>x.d>=0).sort((a,b)=>a.d-b.d||a.h-b.h).map(x=>seanceRow(x)).join('')}</div>`;
  if (tab==='pres') { const past = all.filter(x=>x.st).sort((a,b)=>b.d-a.d);
    body = `<div class="grid g-kpi mb-3">${fs.map(f=>kpi(fname(f), fmtPct(F[f].presence), `${F[f].late} retards · ${F[f].abs} absences`, F[f].icon)).join('')}</div>
    ${S.st.seances.some(x=>x.st==='absent'&&!x.just)?`<div class="alert-strip as-warn mb-3"><i class="fa-solid fa-triangle-exclamation"></i>Une absence n'est pas justifiée. Déposez un justificatif sous 72 h pour éviter une alerte d'absentéisme.</div>`:''}
    <div class="panel tbl"><table class="table"><thead><tr><th>Date</th><th>Formation</th><th>Séance</th><th>Mode</th><th>Statut</th><th>Justificatif</th></tr></thead><tbody>${past.map(x=>`<tr><td class="num">${fmtD(dateOf(x),{day:'2-digit',month:'2-digit'})}</td><td>${fchip(x.f)}</td><td>Séance ${x.n} — ${esc(x.t)}</td><td>${modeLbl(x.mode)}</td><td>${x.st==='present'?pill('Présent','ok'):x.st==='retard'?pill('Retard (12 min)','warn'):pill('Absent','bad')}</td><td>${x.st!=='absent'?'<span class="muted">—</span>':x.just===true?pill('Accepté','ok'):x.just==='pending'?pill('En vérification','info'):`<button class="btn btn-soft btn-sm" data-act="justif" data-id="${x.id}"><i class="fa-solid fa-paperclip me-1"></i>Déposer</button>`}</td></tr>`).join('')}</tbody></table></div>`; }
  if (tab==='ratt') body = `<p class="muted">Séances de rattrapage autorisées par la pédagogie suite à une absence justifiée ou un retard de progression.</p><div class="panel">${S.st.rattrapages.filter(r=>fs.includes(r.f)).map((r,i)=>`<div class="row-item">${datebox(addDays(r.d),r.f)}<div class="ri-main"><div class="ri-t">${esc(r.t)}</div><div class="ri-s">${fchip(r.f)} ${fmtD(addDays(r.d),{weekday:'long',day:'numeric',month:'long'})} · ${r.h}h00 · ${esc(r.place)}</div></div>${r.joined?`<button class="btn btn-ok-soft btn-sm" data-act="ratt" data-i="${i}"><i class="fa-solid fa-check me-1"></i>Inscrit</button>`:`<button class="btn btn-primary btn-sm" data-act="ratt" data-i="${i}">S'inscrire</button>`}</div>`).join('')||empty('Aucun rattrapage autorisé')}</div>`;
  if (tab==='replay') body = `<div class="grid g-3">${all.filter(x=>x.replay).map(x=>`<div class="lib-card c-${x.f}"><button class="pb-art border-0 w-100 rounded" style="background:color-mix(in srgb,var(--fc) 85%,#000);aspect-ratio:16/9" data-act="replay" data-id="${x.id}" aria-label="Lire le replay"><i class="fa-solid fa-circle-play fa-2x"></i></button><div class="d-flex gap-2 align-items-center">${fchip(x.f)}<span class="small muted">${fmtD(dateOf(x),{day:'numeric',month:'short'})} · 2 h 54</span></div><h4>Séance ${x.n} — ${esc(x.t)}</h4></div>`).join('')||empty('Aucun replay disponible')}</div>`;
  return `<ul class="nav nav-tabs mb-3">${tabs.map(t=>`<li class="nav-item"><button class="nav-link ${tab===t[0]?'active':''}" data-act="stab" data-t="${t[0]}">${t[1]}</button></li>`).join('')}</ul>${body}`;
});
ACT.stab = el => { S.ui.stab = el.dataset.t; rerender(); };
ACT.week = el => { const w = +el.dataset.w; S.ui.week = w===0 ? 0 : Math.max(-1, Math.min(1,(S.ui.week||0)+w)); rerender(); };
ACT.seance = el => { const x = S.st.seances.find(s=>s.id===el.dataset.id), d = dateOf(x), virt = x.mode==='Virtuel';
  openModal({title:`${fchip(x.f)} <span class="ms-1">${esc(x.t)}</span>`, body:`<div class="d-flex flex-column gap-2"><div class="stat-line"><span>Date</span><b>${fmtD(d,{weekday:'long',day:'numeric',month:'long'})}</b></div><div class="stat-line"><span>Séance</span><b>N° ${x.n}</b></div><div class="stat-line"><span>Horaire</span><b>${hrs(x)}</b></div><div class="stat-line"><span>Type</span>${modePill(x.mode)}</div><div class="stat-line"><span>Formateur</span><b>${F[x.f].trainer}</b></div><div class="stat-line"><span>${virt?'Lien de la classe virtuelle':'Lieu'}</span><b class="${virt?'mono':''}">${esc(x.place)}</b></div>${x.st?`<div class="stat-line"><span>Présence</span>${x.st==='present'?pill('Présent','ok'):x.st==='retard'?pill('Retard','warn'):pill('Absent','bad')}</div>`:''}<hr><div class="small-caps">Supports</div><div class="row-item px-0"><i class="fa-solid fa-file-pdf" style="color:var(--bad)"></i><div class="ri-main small">Support — ${esc(x.t)}.pdf</div><button class="btn btn-ghost btn-sm" data-act="fake-dl" data-n="Support ${esc(x.t)}"><i class="fa-solid fa-download"></i></button></div>${!virt&&x.d>=0?`<div class="alert-strip as-info"><i class="fa-solid fa-qrcode"></i>Le jour J, scannez le QR code affiché en salle pour valider votre présence.</div>`:''}</div>`,
    foot: virt && x.d>=0 ? `<button class="btn btn-ghost" data-act="copy-link" data-l="${esc(x.place)}">Copier le lien</button><a class="btn btn-primary" href="https://${esc(x.place)}" target="_blank" rel="noopener">Rejoindre la classe</a>` : `<button class="btn btn-ghost" data-bs-dismiss="modal">Fermer</button>`}); };
ACT['copy-link'] = el => { try { navigator.clipboard.writeText('https://'+el.dataset.l).then(()=>toast('Lien copié.'),()=>toast('https://'+el.dataset.l,'info')); } catch(_) { toast('https://'+el.dataset.l,'info'); } };
ACT.justif = el => openModal({title:"Justifier une absence", body:`<form id="jf" data-submit="justif-send" data-id="${el.dataset.id}" novalidate class="d-flex flex-column gap-3"><div><label class="form-label" for="jf-m">Motif</label><select class="form-select" id="jf-m"><option>Raison médicale</option><option>Raison familiale</option><option>Problème de connexion</option><option>Autre</option></select></div><div><label class="form-label" for="jf-f">Pièce justificative</label><input class="form-control" type="file" id="jf-f" required><div class="invalid-feedback">Ajoutez un justificatif (certificat, attestation…).</div></div><div><label class="form-label" for="jf-c">Commentaire</label><textarea class="form-control" id="jf-c" rows="2"></textarea></div></form>`, foot:`<button class="btn btn-primary" type="submit" form="jf">Envoyer</button>`});
ACT['justif-send'] = f => { S.st.seances.find(s=>s.id===f.dataset.id).just = 'pending'; closeModal(); rerender(); toast('Justificatif envoyé au responsable pédagogique.'); };
ACT.ratt = el => { const r = S.st.rattrapages.filter(r=>vf().includes(r.f))[+el.dataset.i]; r.joined = !r.joined; rerender(); toast(r.joined?'Inscription au rattrapage confirmée.':'Inscription annulée.', r.joined?'ok':'info'); };
ACT.replay = el => { const x = S.st.seances.find(s=>s.id===el.dataset.id); openModal({title:`Replay — ${esc(x.t)}`, size:'modal-lg', body:`<div class="rounded d-grid text-white c-${x.f}" style="aspect-ratio:16/9;background:#0b0d17;place-items:center;max-width:100%"><div class="text-center"><i class="fa-solid fa-circle-play fa-3x mb-2" style="color:var(--fc)"></i><div class="small" style="opacity:.7">Lecteur vidéo sécurisé (stockage privé S3) · 2 h 54 min</div></div></div><div class="d-flex justify-content-between mt-3 small muted flex-wrap gap-2"><span>${fchip(x.f)} ${fmtD(dateOf(x),{weekday:'long',day:'numeric',month:'long'})}</span><span>Disponible 30 jours · lecture seule, téléchargement désactivé</span></div>`}); };

/* ----- My To-Do ----- */
const TODO_GROUPS = [['', 'Tous', ()=>true], ['open','À faire', t=>['afaire','reprendre'].includes(t.status)], ['go','En cours', t=>t.status==='encours'], ['wait','Publiés', t=>t.status==='soumis'], ['done','Validés', t=>t.status==='valide']];
view('e-todo','etu','My To-Do','fa-list-check', () => {
  const fs = vf(), all = S.st.todos.filter(t=>fs.includes(t.f)), v = S.ui.todoView || 'list';
  if (S.ui.todoS==null) S.ui.todoS = 'open';
  return `<div class="toolbar"><div class="chips">${TODO_GROUPS.map(([k,l,fn])=>`<button class="chip-filter ${S.ui.todoS===k?'on':''}" data-act="todo-s" data-s="${k}">${l}<span class="n">${all.filter(fn).length}</span></button>`).join('')}</div>
    <div class="ms-auto d-flex gap-2"><input class="form-control form-control-sm" style="width:200px" placeholder="Rechercher…" data-inp="todo-q" value="${esc(S.ui.todoQ||'')}" aria-label="Rechercher un travail">
    <button class="btn btn-ghost btn-sm btn-icon" data-act="todo-view" data-v="${v==='list'?'kanban':'list'}" title="${v==='list'?'Vue tableau':'Vue liste'}" aria-label="${v==='list'?'Vue tableau':'Vue liste'}"><i class="fa-solid ${v==='list'?'fa-table-columns':'fa-list'}"></i></button></div></div>
  <div id="r-todo">${todoRegion()}</div>`;
});
function todoRegion(){
  const q = norm(S.ui.todoQ||''); let all = S.st.todos.filter(t=>vf().includes(t.f) && (!q || norm(t.t).includes(q)));
  if ((S.ui.todoView||'list')==='kanban') return `<div class="kanban">${Object.entries(STATUS).map(([k,v])=>{ const col = all.filter(t=>t.status===k); return `<div class="kcol"><div class="kcol-h"><span>${pill(v[0],v[1])}</span><span class="muted num">${col.length}</span></div>${col.map(t=>`<div class="kcard c-${t.f}" data-act="todo" data-id="${t.id}" role="button" tabindex="0"><div class="t">${esc(t.t)}</div><div class="small muted">${fchip(t.f)} <i class="fa-regular fa-clock ms-1"></i> ${relDay(t.due)}</div></div>`).join('')}</div>`; }).join('')}</div>`;
  const g = TODO_GROUPS.find(x=>x[0]===S.ui.todoS); if (g) all = all.filter(g[2]);
  all.sort((a,b)=>a.due-b.due);
  return all.length ? `<div class="panel">${all.map(todoRow).join('')}</div>` : `<div class="panel">${empty('Aucun travail ici','fa-circle-check')}</div>`;
}
INP['todo-q'] = el => { S.ui.todoQ = el.value; $('#r-todo').innerHTML = todoRegion(); };
ACT['todo-s'] = el => { S.ui.todoS = el.dataset.s; rerender(); };
ACT['todo-view'] = el => { S.ui.todoView = el.dataset.v; rerender(); };
/* Projet attribué par l'administration : lire les consignes → « Je démarre » (l'administration est notifiée)
   → réaliser et corriger dans la classe virtuelle WhatsApp → « Terminer » : joindre et publier (l'administration est notifiée) → validation finale */
const WSTEPS = [['Lire et démarrer','fa-solid fa-play'],['Réaliser · corrections en classe virtuelle','fa-brands fa-whatsapp'],['Terminer et publier','fa-solid fa-cloud-arrow-up'],["Validation de l'administration",'fa-solid fa-circle-check']];
const wStage = st => ({afaire:0, encours:1, reprendre:1, soumis:3, valide:4})[st] ?? 0;
const wSteps = st => { const k = wStage(st); return `<ol class="wsteps">${WSTEPS.map((x,i)=>`<li class="${i<k?'done':i===k?'cur':''}"><span class="wn">${i<k?'<i class="fa-solid fa-check"></i>':`<i class="${x[1]}"></i>`}</span><span class="wl">${x[0]}</span></li>`).join('')}</ol>`; };
function adminNotify(kind, t, txt){ S.anotifs.unshift({id:'an'+Date.now(), kind, t, txt, d:"À l'instant", read:false}); }
ACT.todo = el => { const t = S.st.todos.find(x=>x.id===(el.dataset.id)), k = wStage(t.status), lastAdmin = [...t.hist].reverse().find(h=>h.w==='Administration'), me = `${S.st.student.first} ${S.st.student.last}`;
  const brief = `<div class="small-caps mb-1">Description et consignes</div><p class="mb-2" style="white-space:pre-line">${esc(t.brief)}</p><div class="stat-line mb-1"><span>Type</span><b>${esc(t.type)}${t.mandatory?' · obligatoire':''}</b></div><div class="stat-line mb-1"><span>À rendre avant le</span><b>${fmtD(addDays(t.due),{weekday:'long',day:'numeric',month:'long'})}</b></div><div class="stat-line"><span>Formateur</span><b>${F[t.f].trainer}</b></div>`;
  const files = t.files.length ? t.files.map(f=>`<span class="tag me-1 mb-1"><i class="fa-solid fa-paperclip"></i>${esc(f)}</span>`).join('') : '<span class="small muted">Aucun fichier.</span>';
  let top = '', foot = '';
  if (k===0) { top = `<div class="alert-strip as-info mb-3"><i class="fa-solid fa-book-open"></i><span>Lisez attentivement les consignes, puis cliquez sur <b>Je démarre</b>. L'administration sera informée que vous avez commencé.</span></div>`;
    foot = `<button class="btn btn-ghost" data-bs-dismiss="modal">Plus tard</button><button class="btn btn-primary btn-lg" data-act="todo-start" data-id="${t.id}"><i class="fa-solid fa-play me-2"></i>Je démarre</button>`; }
  else if (k===1) { top = `${t.status==='reprendre'?`<div class="alert-strip as-bad mb-3"><i class="fa-solid fa-rotate-left"></i><span><b>À reprendre.</b> ${esc(lastAdmin?.c||'Votre publication n\'a pas été validée.')}</span></div>`:''}
    <div class="wa-card mb-3"><i class="fa-brands fa-whatsapp"></i><div class="ri-main"><b>Réalisez votre projet, puis publiez-le dans ${CLASSE[t.f]}</b><div class="small muted">Vos formateurs vous y envoient leurs corrections. Revenez ici quand votre travail y est validé.</div></div><button class="btn btn-ghost btn-sm" data-act="wa-open" data-f="${t.f}">Ouvrir le groupe</button></div>
    <details class="finish" ${S.ui.finish===t.id?'open':''}><summary class="btn btn-soft w-100"><i class="fa-solid fa-flag-checkered me-1"></i>J'ai terminé : joindre mon travail</summary>
    <form id="td-form" data-submit="todo-submit" data-id="${t.id}" class="d-flex flex-column gap-2 mt-3" novalidate><label class="dropzone" for="td-files"><i class="fa-solid fa-cloud-arrow-up fa-lg"></i>Joindre la version finale<div class="small">PDF, AI, PSD, PNG, DOCX, XLSX… 200 Mo max</div></label><input type="file" id="td-files" multiple hidden data-chg="td-files"><div id="td-picked" class="small"></div><input class="form-control" id="td-link" type="url" placeholder="Ou un lien (Drive, Behance, Canva…)" aria-label="Lien"><textarea class="form-control" id="td-msg" rows="2" placeholder="Un mot pour l'administration (facultatif)" aria-label="Message"></textarea><label class="d-flex gap-2 small"><input class="form-check-input" type="checkbox" required id="td-ok">Mon travail a été corrigé et validé dans la classe virtuelle</label></form></details>`;
    foot = `<button class="btn btn-ghost" data-bs-dismiss="modal">Fermer</button><button class="btn btn-primary" data-act="todo-finish" data-id="${t.id}"><i class="fa-solid fa-paper-plane me-1"></i>Terminer et publier</button>`; }
  else if (k===3) { top = `<div class="alert-strip as-warn mb-3"><i class="fa-solid fa-hourglass-half"></i><span>Projet terminé et publié. L'administration va le <b>valider définitivement</b>.</span></div><div class="small-caps mb-1">Travail joint</div><div class="mb-3">${files}</div>`; foot = `<button class="btn btn-ghost" data-bs-dismiss="modal">Fermer</button>`; }
  else { top = `<div class="alert-strip as-ok mb-3"><i class="fa-solid fa-circle-check"></i><span>Projet <b>validé définitivement</b>${t.grade?` · ${uApp(t.grade)[0].toLowerCase()}`:''}.</span></div><div class="small-caps mb-1">Travail joint</div><div class="mb-3">${files}</div>`; foot = `<button class="btn btn-ghost" data-bs-dismiss="modal">Fermer</button>`; }
  openModal({title:`${fchip(t.f)} <span class="ms-1">${esc(t.t)}</span>`, size:'modal-lg', body:`${wSteps(t.status)}<div class="row g-4"><div class="col-md-7">${top}${brief}</div><div class="col-md-5"><div class="small-caps mb-2">Historique</div><ul class="timeline">${t.hist.length?t.hist.map(h=>`<li class="${h.w==='Vous'?'cur':'ok'}"><span class="tdot"></span><b class="small">${esc(h.w)}</b> <span class="small muted">· ${relDay(h.d).toLowerCase()}</span><div class="small">${esc(h.c)}</div></li>`).join(''):'<li><span class="tdot"></span><span class="small muted">Projet reçu, pas encore démarré.</span></li>'}</ul></div></div>`, foot}); };
INP['td-files'] = el => { $('#td-picked').innerHTML = fileNames(el).map(n=>`<span class="tag me-1">${esc(n)}</span>`).join(''); };
ACT['wa-open'] = el => toast(`Ouverture de WhatsApp : <b>${esc(CLASSE[el.dataset.f])}</b>`,'info');
ACT['todo-start'] = el => { const t = S.st.todos.find(x=>x.id===el.dataset.id), me = `${S.st.student.first} ${S.st.student.last}`; t.status = 'encours'; t.started = true; t.hist.push({w:'Vous', d:0, c:'Projet démarré.'});
  adminNotify('start', t.t, `${me} a commencé son projet « ${t.t} »`); audit('Projet démarré', `${t.t} — ${me}`); rerender(); ACT.todo({dataset:{id:t.id}}); toast("C'est parti ! L'administration est informée que vous avez commencé."); };
ACT['todo-finish'] = el => { const d = $('details.finish'); if (d && !d.open) { d.open = true; S.ui.finish = el.dataset.id; $('#td-files')?.closest('form')?.scrollIntoView({block:'nearest', behavior:'smooth'}); toast('Joignez votre travail, cochez la case puis cliquez à nouveau sur « Terminer et publier ».','info'); return; }
  const f = $('#td-form'); if (!f.checkValidity()) { f.classList.add('was-validated'); toast('Cochez la case de validation en classe virtuelle.','warn'); return; } ACT['todo-submit'](f); };
ACT['todo-submit'] = f => { const t = S.st.todos.find(x=>x.id===f.dataset.id), files = fileNames($('#td-files')), link = $('#td-link').value.trim(), me = `${S.st.student.first} ${S.st.student.last}`;
  if (!files.length && !link) { toast('Joignez au moins un fichier ou un lien.','warn'); return; }
  t.files.push(...files); if (link) t.files.push(link); t.status = 'soumis'; S.ui.finish = null; t.hist.push({w:'Vous', d:0, c:`Projet terminé et publié${$('#td-msg').value?' — '+$('#td-msg').value:''}.`});
  adminNotify('done', t.t, `${me} a terminé et publié son projet « ${t.t} »`);
  S.st.notifs.unshift({id:'n'+Date.now(),cat:'Travaux',f:t.f,t:`« ${t.t} » est publié. L'administration va le valider.`,d:"À l'instant",read:false});
  audit('Projet publié', `${t.t} — ${me}`); closeModal(); rerender(); toast("Projet publié. L'administration est notifiée et va le valider."); };

/* ----- Bibliothèque ----- */
view('e-bibliotheque','etu','Bibliothèque','fa-book-open', () => {
  const locked = S.st.library.filter(l=>l.f!=='ALL' && !fl().includes(l.f)).length, cats = [...new Set(S.st.library.map(l=>l.cat))];
  return `<div class="toolbar"><div class="grow"><div class="input-group"><span class="input-group-text"><i class="fa-solid fa-magnifying-glass"></i></span><input class="form-control" placeholder="Rechercher un document, un tutoriel…" data-inp="lib-q" aria-label="Rechercher"></div></div><select class="form-select" style="max-width:240px" data-chg="lib-c" aria-label="Catégorie"><option value="">Toutes les catégories</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select></div>
  ${locked?`<div class="alert-strip as-info mb-3"><i class="fa-solid fa-lock"></i>${locked} documents sont réservés à d'autres formations. L'accès suit automatiquement vos inscriptions.</div>`:''}<div id="r-lib">${libRegion()}</div>`;
});
function libRegion(){ const q=(S.ui.libQ||'').toLowerCase(), c=S.ui.libC||'';
  const items = S.st.library.filter(l=>(l.f==='ALL'||vf().includes(l.f)) && (!q||l.t.toLowerCase().includes(q)) && (!c||l.cat===c));
  return items.length ? `<div class="grid g-4">${items.map(l=>`<div class="lib-card"><div class="d-flex justify-content-between"><span class="ft t-${l.type}"><i class="fa-solid ${typeIcon(l.type)}"></i></span>${l.f==='ALL'?pill('Tous','mute',1):fchip(l.f)}</div><h4>${esc(l.t)}</h4><div class="small muted">${l.cat} · ${l.size}</div><div class="d-flex gap-2 mt-auto"><button class="btn btn-ghost btn-sm flex-fill" data-act="lib-open" data-t="${esc(l.t)}">Consulter</button><button class="btn btn-ghost btn-sm" data-act="fake-dl" data-n="${esc(l.t)}" aria-label="Télécharger"><i class="fa-solid fa-download"></i></button></div></div>`).join('')}</div>` : `<div class="panel">${empty('Aucun document trouvé')}</div>`; }
INP['lib-q'] = el => { S.ui.libQ = el.value; $('#r-lib').innerHTML = libRegion(); };
INP['lib-c'] = el => { S.ui.libC = el.value; $('#r-lib').innerHTML = libRegion(); };
ACT['lib-open'] = el => { const l = S.st.library.find(x=>x.t===el.dataset.t); openModal({title:esc(l.t), size:'modal-lg', body:`<div class="rounded p-4" style="background:var(--soft);border:1px solid var(--line);min-height:320px"><div class="d-flex gap-3 align-items-center mb-3"><span class="lib-card p-0 border-0"><span class="ft t-${l.type}"><i class="fa-solid ${typeIcon(l.type)}"></i></span></span><div><b>${esc(l.t)}</b><div class="small muted">${l.cat} · ${l.size} · version 1.${l.t.length%5}</div></div></div><div style="height:10px;width:70%;background:var(--line);border-radius:4px" class="mb-2"></div><div style="height:10px;width:92%;background:var(--line);border-radius:4px" class="mb-2"></div><div style="height:10px;width:84%;background:var(--line);border-radius:4px" class="mb-4"></div><div style="height:140px;background:var(--line);border-radius:8px;opacity:.6"></div><p class="small muted mt-3 mb-0">Aperçu du document dans la visionneuse sécurisée.</p></div>`, foot:`<button class="btn btn-primary" data-act="fake-dl" data-n="${esc(l.t)}"><i class="fa-solid fa-download me-1"></i>Télécharger</button>`}); };

/* ----- Mes projets ----- */
function projectTabs(){ const t = [], fs = vf();
  if (fs.includes('DG')) t.push(['gfx','Travaux graphiques','DG'],['studio','Studio Creative','DG'],['pressbook','Pressbook','DG']);
  if (fs.includes('CM')) t.push(['reco-CM','RECO 60 CM','CM'],['content','Contenus et reporting','CM']);
  if (fs.includes('GIA')) t.push(['reco-GIA','RECO 60 GIA','GIA'],['bureau','Travaux bureautiques','GIA']);
  return t; }
view('e-projets','etu','Mes projets','fa-palette', () => {
  const tabs = projectTabs(); if (!tabs.find(t=>t[0]===S.ui.ptab)) S.ui.ptab = tabs[0][0]; const p = S.ui.ptab;
  const body = p==='gfx' ? projGfx() : p==='studio' ? projStudio() : p==='pressbook' ? projPressbook() : p==='content' ? projContent() : p==='bureau' ? projBureau() : projReco(p.split('-')[1]);
  return `<div class="chips mb-3">${tabs.map(t=>`<button class="chip-filter ${p===t[0]?'on':''}" data-act="ptab" data-p="${t[0]}"><span class="sw d-inline-block rounded-circle me-1" style="width:8px;height:8px;background:var(--${t[2].toLowerCase()})"></span>${t[1]}</button>`).join('')}</div>${body}`;
});
ACT.ptab = el => { S.ui.ptab = el.dataset.p; rerender(); };
function projGfx(){ const items = S.st.todos.filter(t=>t.f==='DG');
  S.st.gfx = S.st.gfx || {t1:[{v:1,src:'logo_pistes.ai',rend:'pistes_nb.png',d:'15/10/2026',st:'Corrigé',c:'Pistes 1 et 3 retenues'}],t4:[{v:1,src:'magazine_v1.indd',rend:'magazine_v1.pdf',d:'20/10/2026',st:'À reprendre',c:'Styles de paragraphe incomplets'}],t3:[{v:1,src:'carte_evc.ai',rend:'carte_v1.pdf',d:'14/10/2026',st:'Corrigé',c:'Marges intérieures'},{v:2,src:'carte_evc_v2.ai',rend:'carte_evc_v2.pdf',d:'19/10/2026',st:'Validé',c:'Validé — très bon travail'}]};
  return `<div class="grid g-2">${items.map(t=>{ const vs = S.st.gfx[t.id]||[]; return `<section class="panel c-DG"><div class="panel-h"><span class="icon-sq"><i class="fa-solid fa-pen-nib"></i></span><div style="min-width:0;flex:1"><h3 class="text-truncate">${esc(t.t)}</h3><span class="sub">Brief reçu · échéance ${relDay(t.due).toLowerCase()}</span></div>${statusPill(t.status)}</div><div class="panel-b"><p class="small mb-2"><b>Brief :</b> ${esc(t.brief)}</p><div class="small-caps mb-1">Historique des versions</div>${vs.length?`<div class="tbl"><table class="table"><thead><tr><th>V.</th><th>Sources</th><th>Rendu</th><th>Statut</th></tr></thead><tbody>${vs.slice().reverse().map(v=>`<tr><td class="mono">v${v.v}</td><td class="small">${esc(v.src)}</td><td class="small">${esc(v.rend)}</td><td>${pill(v.st, v.st==='Validé'?'ok':v.st==='À reprendre'?'bad':v.st==='Déposé'?'acc':'info')}${v.c?`<div class="small muted">${esc(v.c)}</div>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">Aucune version déposée.</p>'}
    ${t.status!=='valide'?`<form data-submit="gfx-add" data-id="${t.id}" class="row g-2 mt-2" novalidate><div class="col-sm-6"><label class="form-label small" for="gs-${t.id}">Fichiers sources</label><input class="form-control form-control-sm" type="file" id="gs-${t.id}" required></div><div class="col-sm-6"><label class="form-label small" for="gr-${t.id}">Rendu (PDF, PNG)</label><input class="form-control form-control-sm" type="file" id="gr-${t.id}" required></div><div class="col-12 text-end"><button class="btn btn-soft btn-sm" type="submit"><i class="fa-solid fa-upload me-1"></i>Déposer la version ${vs.length+1}</button></div></form>`:''}</div></section>`; }).join('')}</div>`; }
ACT['gfx-add'] = f => { const id = f.dataset.id, vs = (S.st.gfx[id] = S.st.gfx[id]||[]); vs.push({v:vs.length+1, src:fileNames($('#gs-'+id))[0], rend:fileNames($('#gr-'+id))[0], d:'22/10/2026', st:'Déposé', c:''}); const t = S.st.todos.find(x=>x.id===id); t.status='soumis'; t.hist.push({w:'Vous',d:0,c:`Version ${vs.length} déposée`}); rerender(); toast(`Version ${vs.length} déposée. Statut : soumis.`); };
function projStudio(){ const s = S.st.studio, steps = [['Inscription', s.registered],['Réception du brief', s.registered],['Soumission du projet', s.submitted],['Présentation devant jury', false],['Résultats', false]];
  const cur = steps.findIndex(x=>!x[1]);
  return `<div class="row g-3"><div class="col-xl-8 d-flex flex-column gap-3">
    <section class="panel c-DG"><div class="panel-b"><div class="d-flex gap-2 align-items-center mb-2 flex-wrap">${pill(`Édition ${s.edition}`,'acc',1)}${pill(`Inscriptions ouvertes jusqu'au ${fmtD(addDays(s.close),{day:'numeric',month:'long'})}`,'info')}</div><h2 class="h3">${esc(s.title)}</h2><p>${esc(s.theme)}</p>
      <div class="steps my-3">${steps.map((x,i)=>`<div class="step ${x[1]?'done':i===cur?'cur':''}"><div class="sn">ÉTAPE ${i+1}</div><b class="small">${x[0]}</b><div class="small mt-1">${x[1]?'<span style="color:var(--ok)"><i class="fa-solid fa-check"></i> Fait</span>':i===cur?'<span style="color:var(--accent)">À faire</span>':'<span class="muted">—</span>'}</div></div>`).join('')}</div>
      ${!s.registered?`<button class="btn btn-primary" data-act="studio-reg"><i class="fa-solid fa-user-plus me-1"></i>M'inscrire à l'édition ${s.edition}</button>`
      : !s.submitted ? `<div class="alert-strip as-ok mb-3"><i class="fa-solid fa-circle-check"></i>Inscription confirmée. Le brief complet est disponible ci-dessous.</div><div class="row-item px-0"><i class="fa-solid fa-file-pdf" style="color:var(--bad)"></i><div class="ri-main"><div class="ri-t">Brief_Studio_Creative_ed${s.edition}.pdf</div><div class="ri-s">Logo, affiche A2, 3 déclinaisons réseaux sociaux · charte fournie</div></div><button class="btn btn-ghost btn-sm" data-act="fake-dl" data-n="Brief Studio Creative"><i class="fa-solid fa-download"></i></button></div><form data-submit="studio-sub" class="d-flex flex-column gap-2 mt-3" novalidate><label class="form-label" for="sc-f">Soumettre mon projet (planche de présentation PDF)</label><input class="form-control" type="file" id="sc-f" required><input class="form-control" id="sc-l" placeholder="Lien Behance ou Drive (facultatif)" aria-label="Lien"><button class="btn btn-primary align-self-start" type="submit">Soumettre le projet</button></form>`
      : `<div class="alert-strip as-info"><i class="fa-solid fa-hourglass-half"></i>Projet soumis. Présentation devant le jury le <b class="ms-1">${fmtD(addDays(s.jury),{weekday:'long',day:'numeric',month:'long'})} à 10h00</b>, Salle Bassam.</div>`}
    </div></section></div>
    <div class="col-xl-4 d-flex flex-column gap-3">${panel('Jury et grille', `<div class="small d-flex flex-column gap-2">${[['Pertinence par rapport au brief',30],['Créativité et originalité',25],['Qualité technique',25],['Présentation orale',20]].map(c=>`<div><div class="stat-line"><span>${c[0]}</span><b>${c[1]} %</b></div>${bar(c[1]*3,'DG')}</div>`).join('')}<hr class="my-2"><div class="muted">Jury : Marc Yao (président), Directrice artistique Agence Sankofa, un alumni EVC 2025.</div></div>`)}
    ${panel('Éditions précédentes', `<div class="tbl"><table class="table"><tbody>${s.past.map(p=>`<tr><td><b>Éd. ${p.ed}</b><div class="small muted">${esc(p.t)}</div></td><td class="text-end">${p.score?`${uAppPill(p.score)}<div class="small muted">${p.rank}</div>`:pill(p.st,'mute')}</td></tr>`).join('')}</tbody></table></div>`, {p0:true})}</div></div>`; }
ACT['studio-reg'] = () => { S.st.studio.registered = true; rerender(); toast("Inscription au Studio Creative confirmée. Brief disponible."); };
ACT['studio-sub'] = () => { S.st.studio.submitted = true; rerender(); toast('Projet soumis au jury du Studio Creative.'); };
function projPressbook(){ const pb = S.st.pressbook, cats = [...new Set(pb.map(p=>p.cat))], c = S.ui.pbc||'';
  return `<div class="d-flex gap-2 align-items-center flex-wrap mb-3"><div class="chips"><button class="chip-filter ${!c?'on':''}" data-act="pbc" data-c="">Toutes</button>${cats.map(x=>`<button class="chip-filter ${c===x?'on':''}" data-act="pbc" data-c="${esc(x)}">${esc(x)}</button>`).join('')}</div><span class="ms-auto d-flex gap-2 align-items-center flex-wrap">${pill(S.st.pressbookStatus, S.st.pressbookStatus==='Validé'?'ok':S.st.pressbookStatus==='En validation pédagogique'?'info':'warn')}<button class="btn btn-ghost btn-sm" data-act="pb-add"><i class="fa-solid fa-plus me-1"></i>Ajouter une réalisation</button>${S.st.pressbookStatus==='En construction'?`<button class="btn btn-primary btn-sm" data-act="pb-final">Déposer le pressbook final</button>`:''}</span></div>
  <div class="grid g-4">${pb.filter(p=>!c||p.cat===c).map((p,i)=>`<div class="pb-tile"><div class="pb-art" style="background:linear-gradient(135deg,${p.c},color-mix(in srgb,${p.c} 55%,#000))">${esc(p.t)}</div><div class="pb-b"><span class="fchip f-DG align-self-start">${esc(p.cat)}</span><b class="small">${esc(p.t)}</b><span class="small muted">${esc(p.desc)}</span></div></div>`).join('')}</div>`; }
ACT.pbc = el => { S.ui.pbc = el.dataset.c; rerender(); };
ACT['pb-add'] = () => openModal({title:'Ajouter une réalisation', body:`<form id="pbf" data-submit="pb-save" novalidate class="d-flex flex-column gap-3"><div><label class="form-label" for="pb-t">Titre du projet</label><input class="form-control" id="pb-t" required><div class="invalid-feedback">Indiquez un titre.</div></div><div><label class="form-label" for="pb-c">Catégorie</label><select class="form-select" id="pb-c"><option>Identité visuelle</option><option>Affiche</option><option>Packaging</option><option>Mise en page</option><option>Illustration</option></select></div><div><label class="form-label" for="pb-d">Description</label><textarea class="form-control" id="pb-d" rows="3" required></textarea></div><div><label class="form-label" for="pb-i">Visuel</label><input class="form-control" type="file" id="pb-i" accept="image/*,.pdf"></div></form>`, foot:`<button class="btn btn-primary" type="submit" form="pbf">Ajouter au pressbook</button>`});
ACT['pb-save'] = () => { const cols = ['#C2255C','#E8620C','#2B8A3E','#1B6EC2','#5F3DC4']; S.st.pressbook.push({t:$('#pb-t').value, cat:$('#pb-c').value, desc:$('#pb-d').value, c:cols[S.st.pressbook.length%5]}); closeModal(); rerender(); toast('Réalisation ajoutée au pressbook.'); };
ACT['pb-final'] = () => confirmBox('Déposer le pressbook final', `Votre pressbook (${S.st.pressbook.length} réalisations) sera transmis pour validation pédagogique. Vous ne pourrez plus le modifier pendant la vérification.`, 'pb-final-ok');
ACT['pb-final-ok'] = () => { S.st.pressbookStatus = 'En validation pédagogique'; closeModal(); rerender(); toast('Pressbook déposé pour validation pédagogique.'); };
function projReco(f){ const r = S.st.reco[f], day = recoDay(f);
  return `<div class="c-${f} d-flex flex-column gap-3">
  <section class="panel"><div class="panel-b"><div class="d-flex gap-3 align-items-start flex-wrap"><div style="flex:1;min-width:240px">${fchip(f)} <span class="small-caps ms-1">Projet pratique sur 60 jours</span><h2 class="h3 mt-1">${esc(r.name)}</h2><div class="small muted">Démarré le ${fmtD(addDays(r.start),{day:'numeric',month:'long'})} · fin prévue le ${fmtD(addDays(r.start+60),{day:'numeric',month:'long'})}</div></div><div class="text-end"><div class="big-pct">J${day}<span class="muted fs-5">/60</span></div><div class="small muted">${60-day} jours restants</div></div></div>
    <div class="daygrid mt-3" aria-label="Avancement jour par jour">${Array.from({length:60},(_,i)=>`<span class="${i<day-1?'d':i===day-1?'t':''}" title="Jour ${i+1}"></span>`).join('')}</div></div></section>
  <div class="steps">${r.steps.map((s,i)=>`<div class="step ${s.st==='done'?'done':s.st==='cur'?'cur':''}"><div class="sn">ÉTAPE ${i+1}</div><b class="small d-block">${esc(s.t)}</b><span class="small muted">${esc(s.d)}</span><div class="mt-2">${s.st==='done'?pill('Terminée','ok'):s.st==='cur'?pill('En cours','acc'):pill('À venir','mute')}</div></div>`).join('')}</div>
  <div class="grid g-kpi">${r.kpi.map(k=>kpi(k.l,k.v,k.s,'fa-chart-line')).join('')}</div>
  ${panel("Journal d'activités", `<div class="tbl"><table class="table"><thead><tr><th>Date</th><th>Activité</th><th>Résultat</th><th>Preuve</th></tr></thead><tbody>${r.log.map(l=>`<tr><td class="num">${fmtD(addDays(l.d),{day:'2-digit',month:'2-digit'})}</td><td>${esc(l.a)}</td><td>${esc(l.r)}</td><td><span class="tag"><i class="fa-solid fa-paperclip"></i>${esc(l.p)}</span></td></tr>`).join('')}</tbody></table></div>
    <form data-submit="reco-log" data-f="${f}" class="row g-2 p-3 border-top" novalidate><div class="col-md-4"><input class="form-control" id="rl-a" placeholder="Activité réalisée" required aria-label="Activité"></div><div class="col-md-4"><input class="form-control" id="rl-r" placeholder="Résultat obtenu" required aria-label="Résultat"></div><div class="col-md-2"><input class="form-control" type="file" id="rl-p" aria-label="Preuve"></div><div class="col-md-2 d-grid"><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`, {p0:true, sub:`${r.log.length} entrées`})}
  ${panel('Rapport final RECO 60', `<div class="d-flex gap-3 align-items-center flex-wrap"><div style="flex:1;min-width:220px" class="small">Le rapport final est attendu au jour 60. Il reprend vos activités, vos résultats chiffrés et vos preuves. Il est transmis au module certification après validation.</div><label class="btn btn-ghost" for="rr-${f}"><i class="fa-solid fa-upload me-1"></i>Déposer le rapport</label><input type="file" id="rr-${f}" hidden data-chg="reco-rep" data-f="${f}"></div>${r.report?`<div class="alert-strip as-ok mt-3"><i class="fa-solid fa-check"></i>${esc(r.report)} déposé, en attente d'évaluation.</div>`:''}`)}
  </div>`; }
ACT['reco-log'] = f => { const r = S.st.reco[f.dataset.f]; r.log.unshift({d:0, a:$('#rl-a').value, r:$('#rl-r').value, p: fileNames($('#rl-p'))[0] || 'aucune pièce'}); rerender(); toast('Activité ajoutée au journal RECO 60.'); };
INP['reco-rep'] = el => { if (!el.files[0]) return; S.st.reco[el.dataset.f].report = el.files[0].name; rerender(); toast('Rapport final RECO 60 déposé.'); };
function projContent(){ const camp = [['Lancement Bissap Délice','Instagram + Facebook','25 000','18 600','6,4 %','En cours'],['Live dégustation','Instagram','0','4 200','9,1 %','Terminée'],['Promo fin de mois','TikTok','15 000','—','—','Planifiée']];
  return `<div class="grid g-kpi mb-3">${kpi('Publications planifiées','20','novembre · 3 plateformes','fa-calendar-plus')}${kpi('Visuels produits','34','dont 12 vidéos courtes','fa-image')}${kpi('Budget publicitaire','40 000 FCFA','exécuté à 62 %','fa-bullhorn')}${kpi('Engagement moyen','6,4 %','objectif 5 %','fa-chart-line')}</div>
  ${panel('Campagnes publicitaires', `<div class="tbl"><table class="table"><thead><tr><th>Campagne</th><th>Plateformes</th><th class="text-end">Budget</th><th class="text-end">Portée</th><th class="text-end">Engagement</th><th>Statut</th></tr></thead><tbody>${camp.map(c=>`<tr><td><b>${c[0]}</b></td><td>${c[1]}</td><td class="text-end num">${c[2]} FCFA</td><td class="text-end num">${c[3]}</td><td class="text-end num">${c[4]}</td><td>${pill(c[5],c[5]==='En cours'?'info':c[5]==='Terminée'?'ok':'mute')}</td></tr>`).join('')}</tbody></table></div>`, {p0:true, cls:'mb-3'})}
  ${panel('Portée hebdomadaire', svgLine(['S1','S2','S3','S4','S5','S6'],[{name:'Portée',values:[1200,2100,2900,4100,5600,7300],color:'var(--cm)',area:true}]))}`; }
function projBureau(){ const tools = [['Word',85],['Excel',70],['PowerPoint',60],['Google Docs',90],['Google Sheets',65],['Google Forms',40],['Canva',75]];
  return `<div class="row g-3"><div class="col-lg-7">${panel('Projets bureautiques', S.st.todos.filter(t=>t.f==='GIA').map(todoRow).join(''), {p0:true})}</div><div class="col-lg-5">${panel('Exercices bureautiques par outil', tools.map(t=>`<div class="mb-2"><div class="stat-line"><span>${t[0]}</span><b>${t[1]} %</b></div>${bar(t[1],'GIA')}</div>`).join(''))}</div></div>`; }

/* ----- Évaluations ----- */
view('e-evaluations','etu','Évaluations','fa-clipboard-check', () => {
  const fs = vf();
  return `<div class="grid g-kpi mb-3">${fs.map(f=>`<div class="kpi c-${f}"><div class="k-l">${fchip(f)} Moyenne pondérée</div><div class="k-v" style="color:var(--fc)">${avgF(f)??'—'}<span class="muted fs-6"> / 20</span></div><div class="k-s">${S.st.evals.filter(e=>e.f===f&&e.note!=null).length} évaluations notées</div></div>`).join('')}</div>
  ${fs.map(f=>panel(`${fchip(f)} <span class="ms-1">${fname(f)}</span>`, `<div class="tbl"><table class="table"><thead><tr><th>Évaluation</th><th>Type</th><th>Date</th><th class="text-center">Coef.</th><th class="text-end">Note</th><th></th></tr></thead><tbody>${S.st.evals.filter(e=>e.f===f).map(e=>`<tr><td><b>${esc(e.t)}</b></td><td>${e.type}</td><td class="num">${fmtD(addDays(e.d),{day:'2-digit',month:'2-digit',year:'numeric'})}</td><td class="text-center num">${e.coef}</td><td class="text-end num">${e.note!=null?`<b style="color:${e.note>=10?'var(--ok)':'var(--bad)'}">${String(e.note).replace('.',',')}</b> / 20`:'—'}</td><td class="text-end">${e.open?`<button class="btn btn-primary btn-sm" data-act="qcm" data-id="${e.id}">Passer le QCM</button>`:e.pending?pill('En correction','warn'):e.note!=null?pill('Publiée','ok'):pill('À venir','mute')}</td></tr>`).join('')}</tbody></table></div>`, {p0:true, cls:'mb-3'})).join('')}`;
});
ACT.qcm = el => { const e = S.st.evals.find(x=>x.id===el.dataset.id), qs = S.st.qcm;
  openModal({title:`${fchip(e.f)} <span class="ms-1">${esc(e.t)}</span>`, size:'modal-lg', body:`<div class="alert-strip as-info mb-3"><i class="fa-regular fa-clock"></i>4 questions · 10 minutes · une seule tentative. La note est publiée immédiatement.</div><form id="qf" data-submit="qcm-done" data-id="${e.id}" class="d-flex flex-column gap-3">${qs.map((q,i)=>`<fieldset class="panel panel-b"><legend class="fs-6 fw-bold mb-2">${i+1}. ${esc(q.q)}</legend>${q.o.map((o,j)=>`<label class="d-flex gap-2 py-1"><input class="form-check-input" type="radio" name="q${i}" value="${j}" required>${esc(o)}</label>`).join('')}</fieldset>`).join('')}</form>`, foot:`<button class="btn btn-primary" type="submit" form="qf">Valider mes réponses</button>`}); };
ACT['qcm-done'] = f => { const e = S.st.evals.find(x=>x.id===f.dataset.id); let ok = 0; S.st.qcm.forEach((q,i)=>{ if (+$(`input[name=q${i}]:checked`).value===q.a) ok++; }); e.note = ok*5; e.open = false; closeModal(); rerender(); toast(`QCM terminé : ${ok}/4 bonnes réponses — ${e.note>=10?'compétence validée':'à reprendre'}.`, e.note>=10?'ok':'warn'); };

/* ----- Mes rapports ----- */
view('e-rapports','etu','Mes rapports','fa-file-lines', () => vf().map(f=>{ const r = S.st.reports[f], locked = ['Version finale soumise','Validé'].includes(r.st);
  return `<section class="panel mb-3 c-${f}"><div class="panel-h">${fchip(f)}<h2>Rapport de fin de formation — ${fname(f)}</h2><div class="tools">${pill(r.st, r.st==='Validé'?'ok':r.st==='En correction'?'warn':r.st==='Version finale soumise'?'info':'mute')}</div></div><div class="panel-b"><div class="row g-3">
    <div class="col-lg-5"><div class="small-caps mb-1">Consignes</div><ul class="small ps-3"><li>15 à 25 pages, police 11 pt, interligne 1,15</li><li>Présentation du parcours, des projets ${f==='DG'?'(Studio Creative, pressbook)':'et du RECO 60'}</li><li>Bilan des compétences acquises et perspectives</li><li>Dépôt final au plus tard le 06/03/2027</li></ul><button class="btn btn-ghost btn-sm" data-act="fake-dl" data-n="Modèle de rapport ${f}"><i class="fa-solid fa-download me-1"></i>Télécharger le modèle</button>
      ${r.comments.length?`<div class="small-caps mt-3 mb-1">Corrections du formateur</div>${r.comments.map(c=>`<div class="msg w-100" style="max-width:none"><b class="small">${esc(c.w)}</b><div class="small">${esc(c.c)}</div></div>`).join('')}`:''}</div>
    <div class="col-lg-7"><div class="small-caps mb-1">Versions</div>${r.versions.length?`<div class="tbl"><table class="table"><thead><tr><th>Version</th><th>Date</th><th>Fichier</th><th>Note</th></tr></thead><tbody>${r.versions.slice().reverse().map(v=>`<tr><td class="mono">v${v.v}${v.final?' · finale':''}</td><td class="num">${v.d}</td><td class="small">${esc(v.file)}</td><td class="small muted">${esc(v.note)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">Aucune version déposée.</p>'}
      ${locked?`<div class="alert-strip as-info mt-3"><i class="fa-solid fa-lock"></i>La version finale est verrouillée pendant la correction. Une fois validé, le rapport est archivé dans la RapportThèque.</div>`:`<form data-submit="rep-up" data-f="${f}" class="row g-2 mt-2" novalidate><div class="col-md-6"><input class="form-control" type="file" id="ru-${f}" accept=".doc,.docx,.pdf" required aria-label="Fichier du rapport"></div><div class="col-md-6"><input class="form-control" id="rn-${f}" placeholder="Note de version" aria-label="Note de version"></div><div class="col-12 d-flex gap-2 justify-content-end flex-wrap"><button class="btn btn-ghost" type="submit"><i class="fa-solid fa-upload me-1"></i>Déposer une nouvelle version</button>${r.versions.length?`<button class="btn btn-primary" type="button" data-act="rep-final" data-f="${f}">Soumettre la version finale</button>`:''}</div></form>`}
    </div></div></div></section>`; }).join(''));
ACT['rep-up'] = f => { const k = f.dataset.f, r = S.st.reports[k]; r.versions.push({v:r.versions.length+1, d:'22/10/2026', file:fileNames($('#ru-'+k))[0], note:$('#rn-'+k).value}); if (r.st==='Non commencé') r.st='Brouillon'; rerender(); toast(`Version ${r.versions.length} enregistrée (modifiable).`); };
ACT['rep-final'] = el => confirmBox('Soumettre la version finale', 'La dernière version déposée deviendra la version finale et ne pourra plus être modifiée. Continuer ?', 'rep-final-ok', `data-f="${el.dataset.f}"`);
ACT['rep-final-ok'] = el => { const r = S.st.reports[el.dataset.f]; r.versions[r.versions.length-1].final = true; r.st = 'Version finale soumise'; closeModal(); rerender(); toast('Version finale soumise au formateur.'); };

/* ----- Certification ----- */
view('e-certification','etu','Certification','fa-award', () => `${isCombined()?`<div class="alert-strip as-info mb-3"><i class="fa-solid fa-circle-info"></i>Votre profil comporte ${fl().length} dossiers de certification indépendants. Chaque formation conserve son propre statut de validation.</div>`:''}
  <div class="grid g-2">${vf().map(f=>{ const c = certCriteria(f), ok = c.filter(x=>x.s==='ok').length, elig = ok===c.length, ko = c.filter(x=>x.s==='ko');
    return `<section class="panel c-${f}" style="border-top:4px solid var(--fc)"><div class="panel-h">${fchip(f)}<h2>Dossier ${fname(f)}</h2><div class="tools"><span class="big-pct fs-3">${Math.round(ok/c.length*100)}%</span></div></div><div class="panel-b">${bar(ok/c.length*100,f)}<div class="mt-2">${c.map(x=>`<div class="crit"><span class="ci ${x.s}"><i class="fa-solid ${x.s==='ok'?'fa-check':x.s==='ko'?'fa-xmark':'fa-hourglass-half'}"></i></span><div style="flex:1;min-width:0"><b class="small">${x.t}</b><div class="small muted">${esc(x.d)}</div></div><a class="small" href="#${x.link}">Voir</a></div>`).join('')}</div>
      <div class="verdict mt-3 ${elig?'as-ok':ko.length?'as-bad':'as-warn'} alert-strip"><i class="fa-solid ${elig?'fa-award':ko.length?'fa-circle-xmark':'fa-hourglass-half'}"></i>${elig?'Éligible : votre dossier est transmis au jury de certification.':ko.length?`Non éligible pour l'instant : ${ko.map(k=>k.t.toLowerCase()).join(', ')} à régulariser.`:`En cours : ${c.length-ok} critère${c.length-ok>1?'s':''} restant${c.length-ok>1?'s':''}.`}</div></div></section>`; }).join('')}</div>`);

/* ----- Mes paiements : combien je dois, quand, et un bouton pour payer ----- */
view('e-paiements','etu','Mes paiements','fa-wallet', () => { const p = payState();
  const st = s => pill(s.status, s.status==='Payé'?'ok':s.status==='En retard'?'bad':s.status==='Partiel'?'warn':'mute');
  return `<section class="panel panel-b mb-3"><div class="paybox"><div style="min-width:0"><div class="small-caps">Reste à payer</div><div class="big" style="${p.late?'color:var(--bad)':''}">${fcfa(p.balance)}</div><div class="small muted">sur ${fcfa(p.total)} · ${fcfa(p.paid)} déjà versés</div></div>
    <div style="flex:1;min-width:200px">${bar(p.paid/p.total*100)}${p.next?`<div class="small mt-2">Prochaine échéance : <b>${fcfa(p.next.amount-p.next.paid)}</b> avant le <b>${p.next.due}</b></div>`:'<div class="small mt-2" style="color:var(--ok)">Formation entièrement soldée</div>'}</div>
    ${p.balance?`<button class="btn btn-primary btn-lg" data-act="pay"><i class="fa-solid fa-mobile-screen me-2"></i>Payer</button>`:''}</div></section>
  <div class="grid g-2x">
    ${panel('Échéancier', p.sched.map(s=>`<div class="row-item c-${s.f}"><span class="icon-sq"><i class="fa-solid ${s.kind==='dep'?'fa-flag':'fa-calendar-check'}"></i></span><div class="ri-main"><div class="ri-t">${fcfa(s.amount)}</div><div class="ri-s">${s.kind==='dep'?'Inscription':'Solde'} · ${esc(F[s.f].name)} · ${s.kind==='dep'?'payé le':'avant le'} ${s.due}</div></div>${st(s)}</div>`).join(''), {p0:true})}
    ${panel('Mes reçus', S.st.pay.tx.slice().reverse().map(t=>`<div class="row-item clickable" data-act="receipt" data-r="${t.ref}"><span class="icon-sq" style="--fc:var(--ok);--fcs:var(--ok-soft)"><i class="fa-solid fa-receipt"></i></span><div class="ri-main"><div class="ri-t">${fcfa(t.amount)}</div><div class="ri-s">${t.d} · ${t.mode}${t.by!=='Aya Kouassi'?' · payé par '+esc(t.by):''}</div></div><i class="fa-solid fa-chevron-right muted"></i></div>`).join(''), {p0:true, tools:`<button class="btn btn-ghost btn-sm" data-act="invoice"><i class="fa-solid fa-file-invoice me-1"></i>Facture</button>`})}
  </div>
  <details class="panel mt-3 more"><summary class="panel-h"><h2>Modalités de paiement</h2><i class="fa-solid fa-chevron-down ms-auto muted chev"></i></summary><div class="panel-b">${p.perF.map(x=>`<div class="stat-line py-1 c-${x.f}"><span>${fchip(x.f)} ${esc(F[x.f].name)}</span><b class="num">${fcfa(x.total)}</b></div><div class="small muted mb-2">${esc(x.rule)}</div>`).join('')}<div class="small muted">Lieu des séances présentielles : ${esc(F[fl()[0]].place)}.</div></div></details>`; });
ACT.pay = () => { const p = payState(), due = p.next ? p.next.amount - p.next.paid : 0; if (!p.balance) { toast('Votre formation est entièrement soldée.','info'); return; }
  const modes = [['Orange Money','fa-mobile-screen'],['MTN MoMo','fa-mobile-screen'],['Moov Money','fa-mobile-screen'],['Wave','fa-mobile-screen'],['Carte bancaire','fa-credit-card'],['Virement','fa-building-columns']];
  openModal({title:'Effectuer un paiement', body:`<form id="payf" data-submit="pay-go" novalidate class="d-flex flex-column gap-3"><div><label class="form-label" for="pay-amt">Montant (FCFA)</label><input class="form-control form-control-lg num" type="number" id="pay-amt" min="1000" max="${p.balance}" step="500" value="${due}" required><div class="form-text muted">Solde restant : ${fcfa(p.balance)}. Le paiement partiel est accepté.</div><div class="invalid-feedback">Montant entre 1 000 FCFA et ${fcfa(p.balance)}.</div></div>
    <div><span class="form-label d-block">Mode de paiement</span><div class="role-pick" style="grid-template-columns:repeat(3,1fr)">${modes.map((m,i)=>`<input type="radio" name="pmode" id="pm-${i}" value="${m[0]}" ${i===0?'checked':''}><label for="pm-${i}"><i class="fa-solid ${m[1]}"></i>${m[0]}</label>`).join('')}</div></div>
    <div><label class="form-label" for="pay-tel">Numéro Mobile Money / référence</label><input class="form-control" id="pay-tel" value="${esc(S.st.student.phone)}" required></div>
    <label class="d-flex gap-2 small"><input class="form-check-input" type="checkbox" id="pay-third" data-chg="pay-third">Paiement effectué par un tiers (parent, employeur…)</label><div id="pay-third-box" hidden><input class="form-control" id="pay-by" placeholder="Nom du payeur" aria-label="Nom du payeur"></div>
    ${isCombined()?`<div><label class="form-label" for="pay-f">Affecter à</label><select class="form-select" id="pay-f"><option value="">Répartition automatique (toutes formations)</option>${fl().map(f=>`<option value="${f}">${fname(f)}</option>`).join('')}</select></div>`:''}</form>`,
    foot:`<button class="btn btn-ghost" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary" type="submit" form="payf"><i class="fa-solid fa-lock me-1"></i>Payer</button>`}); };
INP['pay-third'] = el => $('#pay-third-box').hidden = !el.checked;
ACT['pay-go'] = () => { const amt = +$('#pay-amt').value, mode = $('input[name=pmode]:checked').value, by = $('#pay-third').checked && $('#pay-by').value ? $('#pay-by').value : 'Aya Kouassi';
  const body = $('#modal .modal-body'); body.innerHTML = `<div class="text-center py-4"><div class="spinner-border mb-3" style="color:var(--accent)" role="status"></div><p class="mb-0">${mode.includes('Money')||mode.includes('Wave')||mode.includes('MoMo')?'Validez le paiement sur votre téléphone…':'Traitement sécurisé en cours…'}</p></div>`; $('#modal .modal-footer').hidden = true;
  setTimeout(()=>{ const ref = 'REC-2026-' + (1400 + S.st.pay.tx.length); S.st.pay.tx.push({d:'22/10/2026', ref, mode, amount:amt, by});
    S.st.notifs.unshift({id:'n'+Date.now(),cat:'Paiements',f:null,t:`Paiement de ${fcfa(amt)} reçu (${mode}). Reçu ${ref} disponible.`,d:"À l'instant",read:false});
    body.innerHTML = `<div class="text-center py-3"><div class="icon-sq mx-auto mb-3" style="width:56px;height:56px;font-size:1.4rem;background:var(--ok-soft);color:var(--ok)"><i class="fa-solid fa-check"></i></div><h3 class="h5">Paiement confirmé</h3><p class="muted">${fcfa(amt)} via ${mode}. Votre solde est mis à jour et le reçu <span class="mono">${ref}</span> vous a été envoyé par email et WhatsApp.</p><button class="btn btn-primary" data-act="close-modal">Terminer</button></div>`;
    rerender(); }, 1400); };
ACT.receipt = el => { const t = S.st.pay.tx.find(x=>x.ref===el.dataset.r), s = S.st.student, idx = S.st.pay.tx.indexOf(t), after = S.st.pay.total - S.st.pay.tx.slice(0,idx+1).reduce((a,x)=>a+x.amount,0);
  const r = {...t, s:`${s.first} ${s.last}`, sid:s.matricule, inv:'FAC-2026-0412', after, label:PROFILES[S.profile].label, by: t.by==='Aya Kouassi' ? `${s.first} ${s.last}` : t.by};
  openModal({title:`Reçu ${t.ref}`, size:'modal-lg', body:receiptDoc(r), foot:`<button class="btn btn-ghost" data-act="doc-send" data-n="${t.ref}" data-c="Email"><i class="fa-regular fa-envelope me-1"></i>Recevoir par email</button><button class="btn btn-primary" data-act="fake-dl" data-n="${t.ref}.pdf"><i class="fa-solid fa-file-pdf me-1"></i>Télécharger en PDF</button>`}); };
ACT.invoice = () => { const p = payState(), s = S.st.student;
  openModal({title:'Facture FAC-2026-0412', size:'modal-lg', body:`<div class="cv-sheet"><div class="d-flex justify-content-between flex-wrap gap-2 mb-3"><div class="d-flex gap-3 align-items-center flex-wrap">${logoH('couleur','doc-logo')}<div><b>École Virtuelle des Créatifs</b><div class="small muted">Cocody Riviera 3, Abidjan</div></div></div><div class="text-end small"><b class="mono">FAC-2026-0412</b><div class="muted">Émise le 06/10/2026</div></div></div><div class="small mb-3">Facturé à : <b>${s.first} ${s.last}</b> (${s.matricule})</div><div class="tbl"><table class="table"><thead><tr><th>Désignation</th><th class="text-end">Montant</th></tr></thead><tbody>${fl().map(f=>`<tr><td>Formation ${fname(f)} — ${s.session}</td><td class="text-end num">${fcfa(F[f].price)}</td></tr>`).join('')}${p.remise?`<tr><td>Remise formation combinée</td><td class="text-end num">− ${fcfa(p.remise)}</td></tr>`:''}<tr><td><b>Total</b></td><td class="text-end num"><b>${fcfa(p.total)}</b></td></tr>${S.st.pay.tx.map(t=>`<tr><td class="small muted">Règlement ${t.ref} du ${t.d} (${t.mode})</td><td class="text-end num small">− ${fcfa(t.amount)}</td></tr>`).join('')}<tr><td><b>Reste à payer</b></td><td class="text-end num"><b>${fcfa(p.balance)}</b></td></tr></tbody></table></div><p class="small mt-3 mb-0">Arrêtée la présente facture à la somme de : <b>${amountWords(p.total)}</b>.</p></div>`, foot:`<button class="btn btn-primary" data-act="fake-dl" data-n="FAC-2026-0412.pdf"><i class="fa-solid fa-file-pdf me-1"></i>Exporter en PDF</button>`}); };

/* ----- CV et portfolio ----- */
view('e-cv','etu','CV et portfolio','fa-briefcase', () => { const c = S.st.cv, s = S.st.student;
  return `<div class="row g-3"><div class="col-xl-6 d-flex flex-column gap-3">
    <section class="panel panel-b d-flex gap-3 align-items-center flex-wrap"><div style="flex:1;min-width:200px"><b>Visibilité auprès des recruteurs</b><div class="small muted">Lorsque l'option est active, votre profil apparaît dans la CVthèque consultée par les entreprises partenaires de l'EVC.</div></div><div class="form-check form-switch fs-4 m-0"><input class="form-check-input" type="checkbox" role="switch" id="cv-vis" ${c.visible?'checked':''} data-chg="cv-vis" aria-label="Visible par les recruteurs"></div></section>
    ${panel('Profil professionnel', `<div class="d-flex flex-column gap-3"><div><label class="form-label" for="cv-title">Titre</label><input class="form-control" id="cv-title" value="${esc(c.title)}" data-inp="cv"></div><div><label class="form-label" for="cv-about">Présentation</label><textarea class="form-control" id="cv-about" rows="3" data-inp="cv">${esc(c.about)}</textarea></div><div><label class="form-label" for="cv-avail">Disponibilité</label><select class="form-select" id="cv-avail" data-chg="cv">${['Stage — dès janvier 2027','Stage — immédiatement','Emploi — temps plein','Freelance / missions','Non disponible'].map(o=>`<option ${o===c.avail?'selected':''}>${o}</option>`).join('')}</select></div><div class="small muted"><i class="fa-solid fa-circle-info me-1"></i>Projets et certifications sont ajoutés automatiquement depuis vos formations.</div></div>`)}
    ${panel('Compétences', `<div class="chips mb-3">${S.st.student.skills.map((k,i)=>`<span class="tag">${esc(k)}<button data-act="sk-del" data-i="${i}" aria-label="Retirer ${esc(k)}"><i class="fa-solid fa-xmark"></i></button></span>`).join('')||'<span class="small muted">Aucune compétence ajoutée.</span>'}</div><form data-submit="sk-add" class="input-group"><input class="form-control" id="sk-in" placeholder="Ex. Figma, Meta Ads…" required aria-label="Nouvelle compétence"><button class="btn btn-ghost" type="submit"><i class="fa-solid fa-plus"></i></button></form>`)}
    ${panel('Expériences', `${S.st.student.exp.map((x,i)=>`<div class="row-item px-0"><div class="ri-main"><div class="ri-t small">${esc(x.t)}</div><div class="ri-s">${esc(x.o)} · ${esc(x.d)}</div></div><button class="btn btn-ghost btn-sm" data-act="exp-del" data-i="${i}" aria-label="Supprimer"><i class="fa-regular fa-trash-can"></i></button></div>`).join('')}<form data-submit="exp-add" class="row g-2 mt-1" novalidate><div class="col-md-4"><input class="form-control" id="ex-t" placeholder="Poste" required aria-label="Poste"></div><div class="col-md-4"><input class="form-control" id="ex-o" placeholder="Structure" required aria-label="Structure"></div><div class="col-md-2"><input class="form-control" id="ex-d" placeholder="Année" aria-label="Période"></div><div class="col-md-2 d-grid"><button class="btn btn-ghost" type="submit">Ajouter</button></div></form>`)}
    ${panel('Liens professionnels', `<form data-submit="save-links" class="d-flex flex-column gap-2"><div class="input-group"><span class="input-group-text"><i class="fa-brands fa-linkedin"></i></span><input class="form-control" id="ln-li" value="${esc(S.st.student.links.linkedin)}" aria-label="LinkedIn"></div><div class="input-group"><span class="input-group-text"><i class="fa-brands fa-behance"></i></span><input class="form-control" id="ln-be" value="${esc(S.st.student.links.behance)}" aria-label="Behance"></div><div class="input-group"><span class="input-group-text"><i class="fa-solid fa-link"></i></span><input class="form-control" id="ln-si" value="${esc(S.st.student.links.site)}" placeholder="Site ou portfolio" aria-label="Site web"></div><button class="btn btn-ghost align-self-end" type="submit">Enregistrer</button></form>`)}
    ${panel('Projets réalisés', [...(fl().includes('DG')?S.st.pressbook.map(p=>[p.t,p.cat,'DG']):[]), ...(fl().includes('CM')?[[S.st.reco.CM.name,'RECO 60','CM']]:[]), ...(fl().includes('GIA')?[[S.st.reco.GIA.name,'RECO 60','GIA']]:[])].map(p=>`<div class="row-item"><span class="fchip f-${p[2]}">${p[2]}</span><div class="ri-main"><div class="ri-t small">${esc(p[0])}</div><div class="ri-s">${esc(p[1])}</div></div><div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" checked aria-label="Afficher dans le portfolio"></div></div>`).join(''), {p0:true, sub:'Choisissez ce qui apparaît'})}
  </div><div class="col-xl-6"><div class="small-caps mb-2">Aperçu vu par les recruteurs</div><div class="cv-sheet" id="cv-prev">${cvPreview()}</div></div></div>`; });
function cvPreview(){ const c = S.st.cv, s = S.st.student;
  return `<div class="d-flex gap-3 align-items-center">${avatar(s.first+' '+s.last,'lg',S.st.photo)}<div style="min-width:0"><h3>${esc(s.first)} ${esc(s.last)}</h3><div class="fw-semibold" style="color:var(--accent)">${esc(c.title)}</div><div class="small muted">${esc(s.city)} · ${esc(s.email)}</div></div></div>
  <div class="d-flex gap-2 mt-3 flex-wrap">${pill(c.avail,'info')}${c.visible?pill('Visible dans la CVthèque','ok'):pill('Profil masqué','mute')}</div>
  <div class="cv-sec">Profil</div><p class="mb-0">${esc(c.about)}</p>
  <div class="cv-sec">Compétences</div><div class="chips">${s.skills.map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div>
  <div class="cv-sec">Expériences</div>${s.exp.map(x=>`<div class="d-flex justify-content-between gap-2"><span><b>${esc(x.t)}</b> — ${esc(x.o)}</span><span class="muted small">${esc(x.d)}</span></div>`).join('')}
  <div class="cv-sec">Formation et certifications</div>${fl().map(f=>`<div class="d-flex justify-content-between gap-2"><span>${fchip(f)} ${fname(f)} — EVC</span><span class="muted small">${certPct(f)===100?'Certifiée':'En cours'}</span></div>`).join('')}
  <div class="cv-sec">Liens</div><div class="small d-flex flex-column gap-1">${s.links.linkedin?`<span><i class="fa-brands fa-linkedin me-1"></i>${esc(s.links.linkedin)}</span>`:''}${s.links.behance?`<span><i class="fa-brands fa-behance me-1"></i>${esc(s.links.behance)}</span>`:''}${s.links.site?`<span><i class="fa-solid fa-link me-1"></i>${esc(s.links.site)}</span>`:''}</div>`; }
INP.cv = () => { const c = S.st.cv; c.title = $('#cv-title').value; c.about = $('#cv-about').value; c.avail = $('#cv-avail').value; $('#cv-prev').innerHTML = cvPreview(); };
INP['cv-vis'] = el => { S.st.cv.visible = el.checked; $('#cv-prev').innerHTML = cvPreview(); toast(el.checked?'Profil visible par les recruteurs partenaires.':'Profil masqué de la CVthèque.','info'); };

/* ----- Notifications ----- */
view('e-notifications','etu','Notifications','fa-bell', () => { const cats = ['Communiqués','Séances','Travaux','Évaluations','Paiements','Projets','Certifications','Messages'], c = S.ui.nc || '';
  const list = S.st.notifs.filter(n=>!c||n.cat===c), icons = {Communiqués:'fa-bullhorn',Séances:'fa-calendar-days',Travaux:'fa-list-check',Évaluations:'fa-clipboard-check',Paiements:'fa-wallet',Projets:'fa-palette',Certifications:'fa-award',Annonces:'fa-bullhorn',Messages:'fa-comments'};
  return `<div class="toolbar"><div class="chips grow"><button class="chip-filter ${!c?'on':''}" data-act="nc" data-c="">Toutes</button>${cats.map(x=>`<button class="chip-filter ${c===x?'on':''}" data-act="nc" data-c="${x}">${x}</button>`).join('')}</div><button class="btn btn-ghost btn-sm" data-act="n-all"><i class="fa-solid fa-check-double me-1"></i>Tout marquer comme lu</button></div>
  <div class="panel">${list.map(n=>`<div class="row-item clickable ${n.read?'':'unread'} ps-4" data-act="n-read" data-id="${n.id}"><span class="icon-sq ${n.f?'c-'+n.f:''}"><i class="fa-solid ${icons[n.cat]}"></i></span><div class="ri-main"><div class="${n.read?'':'fw-semibold'}">${esc(n.t)}</div><div class="ri-s">${n.cat}${n.f?' · '+fchip(n.f):''} · ${n.d}</div></div></div>`).join('')||empty('Aucune notification')}</div>`; });
ACT.nc = el => { S.ui.nc = el.dataset.c; rerender(); };
ACT['n-read'] = el => { const n = S.st.notifs.find(x=>x.id===el.dataset.id); n.read = true; rerender(); if (n.body) commOpen(n); };
/* Communiqués de l'administration : lecture, bandeau d'accueil, fenêtre pour les messages importants */
function commOpen(n){ n.read = true; openModal({title:`<i class="fa-solid fa-bullhorn me-2" style="color:var(--accent)"></i>${esc(n.t)}`, body:`<div class="small muted mb-3">Communiqué de l'administration · ${n.d}${n.ch?` · reçu aussi par ${n.ch.filter(x=>x!=='Espace étudiant').join(' et ')||'votre espace'}`:''}</div><p class="mb-0" style="white-space:pre-line">${esc(n.body)}</p>`, foot:`<button class="btn btn-primary" data-act="close-modal">J'ai lu</button>`}); }
function commBanner(){ const L = S.st.notifs.filter(n=>n.comm && !n.read); if (!L.length) return '';
  return L.slice(0,2).map(n=>`<div class="alert-strip as-info mb-3 comm-banner"><i class="fa-solid fa-bullhorn"></i><span class="ri-main"><b>Communiqué de l'administration</b> · ${esc(n.t)}</span><button class="btn btn-primary btn-sm ms-auto" data-act="n-read" data-id="${n.id}">Lire</button></div>`).join(''); }
function commPopup(){ const n = S.st && S.st.notifs.find(x=>x.comm && x.imp && !x.read && !x.popped); if (n) { n.popped = true; setTimeout(()=>commOpen(n), 400); } }
ACT['n-all'] = () => { S.st.notifs.forEach(n=>n.read=true); rerender(); toast('Toutes les notifications sont lues.'); };

/* ----- Messagerie (partagée avec le formateur) ----- */
function messagingView(threads, me){
  if (!threads.find(t=>t.id===S.ui.thread)) S.ui.thread = threads[0]?.id; const th = threads.find(t=>t.id===S.ui.thread);
  return `<div class="panel"><div class="row g-0"><div class="col-md-4 border-end"><div class="p-3 border-bottom d-flex gap-2"><input class="form-control form-control-sm" placeholder="Rechercher…" aria-label="Rechercher une conversation"><button class="btn btn-primary btn-sm btn-icon" data-act="msg-new" aria-label="Nouveau message"><i class="fa-solid fa-pen"></i></button></div>${threads.map(t=>`<div class="row-item clickable ${t.id===S.ui.thread?'':''}" style="${t.id===S.ui.thread?'background:var(--soft)':''}" data-act="thread" data-id="${t.id}">${avatar(t.who,'sm')}<div class="ri-main"><div class="ri-t small">${esc(t.who)}</div><div class="ri-s text-truncate">${esc(t.msgs[t.msgs.length-1].t)}</div></div></div>`).join('')}</div>
    <div class="col-md-8 d-flex flex-column">${th?`<div class="p-3 border-bottom d-flex align-items-center gap-2">${avatar(th.who,'sm')}<div><b>${esc(th.who)}</b><div class="small muted">${esc(th.role)}</div></div></div><div class="thread" id="thread">${th.msgs.map(m=>`<div class="msg ${m.me?'me':''}">${esc(m.t)}<small>${m.d}</small></div>`).join('')}</div><form data-submit="msg-send" class="p-3 border-top d-flex gap-2 mt-auto"><input class="form-control" id="msg-in" placeholder="Écrire un message…" required aria-label="Message"><label class="btn btn-ghost btn-icon" for="msg-file" title="Joindre un fichier"><i class="fa-solid fa-paperclip"></i></label><input type="file" id="msg-file" hidden><button class="btn btn-primary" type="submit"><i class="fa-solid fa-paper-plane"></i></button></form>`:empty('Aucune conversation')}</div></div></div>`;
}
const threadsFor = () => S.role==='etu' ? S.st.threads.filter(t=>!t.f||fl().includes(t.f)) : (S.tthreads = S.tthreads || [{id:'tm1',who:'Aya Kouassi',role:'Étudiante DG · EVC-26-0142',msgs:clone(SEED.threads[0].msgs).map(m=>({...m,me:!m.me}))},{id:'tm2',who:'Responsable pédagogique',role:'Administration',msgs:[{me:false,t:'Merci de finaliser les corrections du magazine avant vendredi.',d:'Hier 08:30'}]}]);
view('e-messagerie','etu','Messagerie','fa-comments', () => messagingView(threadsFor()), () => { const t=$('#thread'); if(t) t.scrollTop = t.scrollHeight; });
ACT.thread = el => { S.ui.thread = el.dataset.id; rerender(); };
ACT['msg-send'] = () => { const th = threadsFor().find(t=>t.id===S.ui.thread), txt = $('#msg-in').value.trim(), file = fileNames($('#msg-file'))[0]; th.msgs.push({me:true, t: txt + (file?` (pièce jointe : ${file})`:''), d:"À l'instant"}); rerender();
  const id = S.ui.thread, v = S.view; setTimeout(()=>{ if (S.view===v && S.ui.thread===id) { th.msgs.push({me:false,t:'Message bien reçu, je vous réponds dans la journée.',d:"À l'instant"}); rerender(); } }, 1800); };
ACT['msg-new'] = () => { const rec = S.role==='etu' ? [...fl().flatMap(f=>[`${F[f].trainer} — Formateur ${f}`]),'Service financier','Scolarité','Responsable pédagogique','Support technique'] : ['Aya Kouassi','Grace Mensah','Responsable pédagogique','DG — niveau débutant'];
  openModal({title:'Nouveau message', body:`<form id="nm" data-submit="msg-create" class="d-flex flex-column gap-3"><div><label class="form-label" for="nm-to">Destinataire</label><select class="form-select" id="nm-to">${rec.map(r=>`<option>${esc(r)}</option>`).join('')}</select><div class="form-text muted">Seuls les responsables autorisés pour vos formations sont proposés.</div></div><div><label class="form-label" for="nm-t">Message</label><textarea class="form-control" id="nm-t" rows="4" required></textarea></div></form>`, foot:`<button class="btn btn-primary" type="submit" form="nm">Envoyer</button>`}); };
ACT['msg-create'] = () => { const who = $('#nm-to').value.split(' — ')[0], list = threadsFor(); let th = list.find(t=>t.who===who); if (!th) { th = {id:'m'+Date.now(), who, role:$('#nm-to').value.split(' — ')[1]||'EVC', f:null, msgs:[]}; (S.role==='etu'?S.st.threads:S.tthreads).unshift(th); } th.msgs.push({me:true,t:$('#nm-t').value,d:"À l'instant"}); S.ui.thread = th.id; closeModal(); rerender(); toast('Message envoyé.'); };

/* ----- Assistance ----- */
view('e-assistance','etu','Assistance','fa-life-ring', () => `<div class="row g-3"><div class="col-xl-7 d-flex flex-column gap-3">
  ${panel('Mes demandes', `<div class="tbl"><table class="table"><thead><tr><th>Ticket</th><th>Objet</th><th>Catégorie</th><th>Priorité</th><th>Statut</th></tr></thead><tbody>${S.st.tickets.map(t=>`<tr><td class="mono">${t.id}</td><td><b>${esc(t.t)}</b><div class="small muted">${t.d}</div></td><td>${t.cat}</td><td>${pill(t.prio, t.prio==='Haute'?'bad':t.prio==='Moyenne'?'warn':'mute',1)}</td><td>${pill(t.st, t.st==='Résolu'?'ok':t.st==='En cours'?'info':'acc')}</td></tr>`).join('')}</tbody></table></div>`, {p0:true})}
  ${panel('Questions fréquentes', `<div class="accordion" id="faq">${[['Comment justifier une absence ?','Dans Mes séances > Présences, cliquez sur « Déposer » à côté de l\'absence concernée. Le justificatif est vérifié sous 72 h.'],['Je n\'ai pas reçu mon reçu Mobile Money','Les reçus sont générés automatiquement dans Mes paiements. S\'il manque, ouvrez un ticket « Paiement » avec la référence de la transaction.'],['Puis-je modifier mon nom ou ma date de naissance ?','Non, ces informations officielles sont modifiables uniquement par l\'administration. Ouvrez un ticket « Scolarité ».'],['Comment accéder au replay d\'une séance ?','Dans Mes séances > Replays. Les vidéos restent disponibles 30 jours.']].map((q,i)=>`<div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#fq${i}">${q[0]}</button></h3><div id="fq${i}" class="accordion-collapse collapse" data-bs-parent="#faq"><div class="accordion-body small">${q[1]}</div></div></div>`).join('')}</div>`)}
  </div><div class="col-xl-5">${panel('Nouvelle demande', `<form data-submit="ticket" class="d-flex flex-column gap-3" novalidate><div><label class="form-label" for="tk-cat">Catégorie</label><select class="form-select" id="tk-cat"><option>Accès plateforme</option><option>Pédagogie</option><option>Paiement</option><option>Scolarité</option><option>Certification</option><option>Technique</option></select></div><div><label class="form-label" for="tk-prio">Priorité</label><select class="form-select" id="tk-prio"><option>Basse</option><option selected>Moyenne</option><option>Haute</option></select></div><div><label class="form-label" for="tk-t">Objet</label><input class="form-control" id="tk-t" required><div class="invalid-feedback">Indiquez l'objet de la demande.</div></div><div><label class="form-label" for="tk-d">Description</label><textarea class="form-control" id="tk-d" rows="4" required></textarea></div><div><label class="form-label" for="tk-f">Capture ou pièce jointe</label><input class="form-control" type="file" id="tk-f"></div><button class="btn btn-primary" type="submit">Envoyer la demande</button></form>`)}</div></div>`);
ACT.ticket = f => { const id = 'TCK-' + (2080 + S.st.tickets.length); S.st.tickets.unshift({id, cat:$('#tk-cat').value, prio:$('#tk-prio').value, t:$('#tk-t').value, st:'Ouvert', d:'22/10/2026'}); S.tickets.unshift({id, from:'Aya Kouassi', cat:$('#tk-cat').value, prio:$('#tk-prio').value, t:$('#tk-t').value, st:'Ouvert', to:'—', d:'22/10/2026'}); rerender(); toast(`Demande ${id} créée. Réponse sous 24 h ouvrées.`); };

/* ----- Paramètres ----- */
view('e-parametres','etu','Paramètres','fa-gear', () => { const cats = ['Séances','Travaux','Évaluations','Paiements','Projets','Certifications','Annonces','Messages'], ch = ['Plateforme','Email','WhatsApp','SMS'];
  return `<div class="row g-3"><div class="col-xl-7">${panel('Préférences de notification', `<div class="tbl"><table class="table"><thead><tr><th>Catégorie</th>${ch.map(c=>`<th class="text-center">${c}</th>`).join('')}</tr></thead><tbody>${cats.map((c,i)=>`<tr><td>${c}</td>${ch.map((x,j)=>`<td class="text-center"><input class="form-check-input" type="checkbox" ${j===0||(j===1&&i<6)||(j===2&&[0,1,3].includes(i))?'checked':''} ${j===0?'disabled':''} aria-label="${c} par ${x}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`, {p0:true, tools:`<button class="btn btn-primary btn-sm" data-act="saved">Enregistrer</button>`})}</div>
  <div class="col-xl-5 d-flex flex-column gap-3">${panel('Affichage', `<div class="d-flex flex-column gap-3"><div><label class="form-label" for="pr-theme">Thème</label><select class="form-select" id="pr-theme" data-chg="theme-sel"><option value="auto" ${S.theme==='auto'?'selected':''}>Automatique (système)</option><option value="light" ${S.theme==='light'?'selected':''}>Clair</option><option value="dark" ${S.theme==='dark'?'selected':''}>Sombre</option></select></div><div><label class="form-label" for="pr-lang">Langue</label><select class="form-select" id="pr-lang"><option>Français</option><option>English</option></select></div></div>`)}
  ${panel('Sécurité', `<div class="d-flex justify-content-between align-items-center gap-2 mb-3"><div><b class="small">Double authentification</b><div class="small muted">Code par SMS ou application</div></div><div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" role="switch" aria-label="Activer la double authentification" data-chg="mfa-toggle"></div></div><div class="small-caps mb-1">Sessions actives</div>${[['Chrome · Windows','Abidjan · maintenant',1],['Application mobile · Android','Abidjan · il y a 2 h',0]].map((x,i)=>`<div class="row-item px-0"><i class="fa-solid ${i?'fa-mobile-screen':'fa-laptop'} muted"></i><div class="ri-main"><div class="ri-t small">${x[0]}</div><div class="ri-s">${x[1]}</div></div>${x[2]?pill('Cet appareil','ok'):`<button class="btn btn-ghost btn-sm" data-act="saved" data-m="Session déconnectée.">Déconnecter</button>`}</div>`).join('')}`)}</div></div>`; });
INP['theme-sel'] = el => { S.theme = el.value; applyTheme(); rerender(); };
INP['mfa-toggle'] = el => toast(el.checked?'Double authentification activée.':'Double authentification désactivée.', el.checked?'ok':'warn');
ACT.saved = el => toast(el.dataset.m || 'Préférences enregistrées.');

/* ----- Web TV : les supports de formation diffusés en vidéo ----- */
const mmss = s => `${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const tvProg = id => S.st.tv.prog[id] || 0;
function tvCurrent(vids){ return vids.find(v=>v.id===S.st.tv.cur) || vids.find(v=>tvProg(v.id)>0 && tvProg(v.id)<1) || vids.find(v=>tvProg(v.id)<1) || vids[0]; }
view('e-webtv','etu','Web TV','fa-tv', () => {
  const vids = S.videos.filter(v=>vf().includes(v.f) && v.pub); if (!vids.length) return `<div class="panel">${empty('Aucune vidéo publiée pour le moment','fa-tv')}</div>`;
  const cur = tvCurrent(vids); S.st.tv.cur = cur.id; const p = tvProg(cur.id), i = vids.indexOf(cur), nxt = vids[i+1];
  const filt = S.ui.tvf || 'all', q = norm(S.ui.tvq||'');
  const list = vids.filter(v => (filt==='all' || (filt==='go' && tvProg(v.id)>0 && tvProg(v.id)<1) || (filt==='new' && !tvProg(v.id)) || (filt==='done' && tvProg(v.id)>=1)) && (!q || norm(v.t+' '+v.mod).includes(q)));
  const groups = []; list.forEach(v => { const k = v.f+'|'+v.mod; let g = groups.find(x=>x.k===k); if (!g) groups.push(g = {k, f:v.f, mod:v.mod, items:[]}); g.items.push(v); });
  const doneN = vids.filter(v=>tvProg(v.id)>=1).length;
  return `<div class="row g-3">
  <div class="col-xl-8">
    <div class="tv-player c-${cur.f} ${S.st.tv.playing?'playing':''}" id="tv-player" data-id="${cur.id}">
      <div class="tv-screen" data-act="tv-toggle"><div class="tv-bg"></div><div class="tv-cap"><span class="tv-live">${fchip(cur.f)} ${cur.n?"Séance "+cur.n:esc(cur.mod)}</span><div class="tv-title">${esc(cur.t)}</div></div><span class="tv-big" aria-hidden="true"><i class="fa-solid fa-play"></i></span><div class="tv-eq" aria-hidden="true"><i></i><i></i><i></i><i></i></div></div>
      <div class="tv-bar"><button class="tv-btn" data-act="tv-toggle" aria-label="Lecture / pause"><i class="fa-solid fa-play tv-i-play"></i><i class="fa-solid fa-pause tv-i-pause"></i></button><button class="tv-btn" data-act="tv-back" aria-label="Reculer de 10 secondes"><i class="fa-solid fa-rotate-left"></i></button>
        <span class="tv-time num" id="tv-time">${mmss(p*cur.dur*60)} / ${mmss(cur.dur*60)}</span><div class="tv-track" data-act="tv-seek" role="slider" aria-label="Position" aria-valuenow="${Math.round(p*100)}"><span id="tv-fill" style="width:${p*100}%"></span></div>
        <button class="tv-btn tv-speed" data-act="tv-speed" aria-label="Vitesse">${S.st.tv.speed}×</button><button class="tv-btn" data-act="tv-fs" aria-label="Plein écran"><i class="fa-solid fa-expand"></i></button></div>
    </div>
    <div class="d-flex justify-content-between align-items-start gap-3 flex-wrap mt-3"><div style="min-width:0"><h2 class="h5 mb-1">${esc(cur.t)}</h2><div class="small muted">${esc(F[cur.f].name)} · ${cur.n?'Replay de la séance '+cur.n:esc(cur.mod)} · ${cur.dur} min</div></div>
      <div class="d-flex gap-2 flex-wrap"><button class="btn btn-ghost btn-sm" data-act="fake-dl" data-n="${esc(cur.t)}.pdf"><i class="fa-solid fa-file-arrow-down me-1"></i>Support PDF</button>${p<1?`<button class="btn btn-ghost btn-sm" data-act="tv-done" data-id="${cur.id}"><i class="fa-solid fa-check me-1"></i>Marquer comme vue</button>`:''}${nxt?`<button class="btn btn-primary btn-sm" data-act="tv-pick" data-id="${nxt.id}">Vidéo suivante <i class="fa-solid fa-forward ms-1"></i></button>`:''}</div></div>
    <p class="small muted mt-2 mb-0"><i class="fa-solid fa-circle-info me-1"></i>Aperçu : dans la version installée, la vidéo du cours est diffusée ici (hébergement EVC, YouTube non répertorié ou Vimeo).</p>
  </div>
  <div class="col-xl-4"><section class="panel tv-list"><div class="panel-h"><h2>Mes cours en vidéo</h2><span class="sub">${doneN} / ${vids.length} vues</span></div>
    <div class="p-2 d-flex flex-column gap-2"><input class="form-control form-control-sm" placeholder="Rechercher une vidéo…" data-inp="tv-q" value="${esc(S.ui.tvq||'')}" aria-label="Rechercher une vidéo"><div class="chips">${[['all','Toutes'],['go','En cours'],['new','Non vues'],['done','Vues']].map(([k,l])=>`<button class="chip-filter ${filt===k?'on':''}" data-act="tv-f" data-f="${k}">${l}</button>`).join('')}</div></div>
    <div class="tv-scroll" id="tv-scroll">${groups.map(g=>`<details ${g.items.some(v=>v.id===cur.id)||q||filt!=='all'?'open':''} class="tv-grp c-${g.f}"><summary>${fchip(g.f)}<span>${g.mod==='Séances'?'Séances — '+esc(F[g.f].name):esc(g.mod)}</span><small>${g.items.filter(v=>tvProg(v.id)>=1).length}/${g.items.length}</small></summary>${g.items.map(v=>{ const pv = tvProg(v.id); return `<button class="tv-item ${v.id===cur.id?'on':''}" data-act="tv-pick" data-id="${v.id}"><span class="tv-th"><i class="fa-solid ${pv>=1?'fa-check':v.id===cur.id?'fa-volume-high':'fa-play'}"></i></span><span class="tv-meta"><span class="tv-t">${esc(v.t)}</span><span class="tv-d">${v.dur} min${pv>0&&pv<1?` · ${Math.round(pv*100)} %`:''}</span>${pv>0&&pv<1?`<span class="tv-p"><span style="width:${pv*100}%"></span></span>`:''}</span></button>`; }).join('')}</details>`).join('') || empty('Aucune vidéo')}</div></section></div></div>`;
}, () => { const on = $('.tv-item.on'); if (on) on.scrollIntoView({block:'nearest'}); if (S.st.tv.playing) tvRun(); });
let TV_T = null;
function tvPaint(v){ const p = tvProg(v.id), f = $('#tv-fill'), t = $('#tv-time'); if (f) f.style.width = p*100+'%'; if (t) t.textContent = `${mmss(p*v.dur*60)} / ${mmss(v.dur*60)}`; }
function tvRun(){ clearInterval(TV_T); TV_T = setInterval(() => { const el = $('#tv-player'); if (!el || !S.st || !S.st.tv.playing) { clearInterval(TV_T); return; }
  const v = S.videos.find(x=>x.id===el.dataset.id); let p = tvProg(v.id); if (p>=1) p = 0;
  p = Math.min(1, p + 4*S.st.tv.speed/(v.dur*60)); S.st.tv.prog[v.id] = p; tvPaint(v);
  if (p>=1) { S.st.tv.playing = false; clearInterval(TV_T); toast('Vidéo terminée.'); rerender(); } }, 250); }
Object.assign(ACT, {
  'tv-toggle': () => { const el = $('#tv-player'); if (!el) return; S.st.tv.playing = !S.st.tv.playing; el.classList.toggle('playing', S.st.tv.playing); if (S.st.tv.playing) tvRun(); },
  'tv-pick': el => { S.st.tv.cur = el.dataset.id; S.st.tv.playing = true; rerender(); },
  'tv-back': () => { const v = S.videos.find(x=>x.id===S.st.tv.cur); S.st.tv.prog[v.id] = Math.max(0, tvProg(v.id) - 10/(v.dur*60)); tvPaint(v); },
  'tv-seek': (el, e) => { const r = el.getBoundingClientRect(), v = S.videos.find(x=>x.id===S.st.tv.cur); S.st.tv.prog[v.id] = Math.max(0, Math.min(.999, (e.clientX-r.left)/r.width)); tvPaint(v); },
  'tv-speed': el => { const sp = [1,1.25,1.5,2], i = sp.indexOf(S.st.tv.speed); S.st.tv.speed = sp[(i+1)%sp.length]; el.textContent = S.st.tv.speed+'×'; },
  'tv-fs': () => { const el = $('#tv-player'); try { document.fullscreenElement ? document.exitFullscreen() : el.requestFullscreen(); } catch(_){} },
  'tv-done': el => { S.st.tv.prog[el.dataset.id] = 1; S.st.tv.playing = false; rerender(); toast('Vidéo marquée comme vue.'); },
  'tv-f': el => { S.ui.tvf = el.dataset.f; rerender(); },
  'tv-resume': el => { S.st.tv.cur = el.dataset.id; S.st.tv.playing = true; closeModal(); go('e-webtv'); }
});
INP['tv-q'] = el => { S.ui.tvq = el.value; clearTimeout(INP._tvq); INP._tvq = setTimeout(()=>{ rerender(); const i = $('[data-inp=tv-q]'); if (i){ i.focus(); i.setSelectionRange(i.value.length,i.value.length); } }, 250); };

/* ----- Mes créneaux : choisir sa disponibilité et réserver une séance individuelle ----- */
const rdvDay = d => addDays(d);
const rdvFree = (f, d, t) => rdvDay(d).getDay()!==0 && (hueOf(f+d+t) % 3 !== 0) && !S.st.rdv.some(r=>r.f===f && r.d===d && r.t===t && r.st!=='Annulé');
view('e-creneaux','etu','Mes créneaux','fa-clock', () => {
  const fs = vf(), rf = S.ui.rdvF && fs.includes(S.ui.rdvF) ? S.ui.rdvF : fs[0], days = Array.from({length:14},(_,i)=>i+1).filter(d=>rdvDay(d).getDay()!==0).slice(0,10);
  const rd = S.ui.rdvD && days.includes(S.ui.rdvD) ? S.ui.rdvD : days[0], mine = S.st.rdv.filter(r=>r.st!=='Annulé');
  return `<p class="muted mb-3" style="max-width:720px">Choisissez votre disponibilité parmi les créneaux attribués à votre formation. Vous pouvez aussi réserver une séance individuelle avec votre formateur.</p>
  ${fs.map(f => { const sl = S.slots.filter(x=>x.f===f), chosen = S.st.slot[f]; return `<section class="panel mb-3 c-${f}"><div class="panel-h"><h2>${fchip(f)} <span class="ms-1">${esc(F[f].name)}</span></h2><span class="sub">${chosen?'Créneau choisi':'Choisissez votre créneau de cours'}</span></div><div class="panel-b"><div class="slot-grid">${sl.map(x=>{ const full = x.taken>=x.cap && chosen!==x.id, on = chosen===x.id; return `<div class="slot ${on?'on':''} ${full?'full':''}"><div class="d-flex justify-content-between align-items-start gap-2"><div><div class="fw-bold">${esc(x.day)}</div><div class="small">${esc(x.h)}</div></div>${pill(x.mode, x.mode==='En ligne'?'info':x.mode==='Hybride'?'acc':'mute', 1)}</div><div class="small muted">${esc(x.note)}</div>${bar(x.taken/x.cap*100,f)}<div class="d-flex justify-content-between align-items-center"><span class="small muted">${full?'Complet':`${x.cap-x.taken} place${x.cap-x.taken>1?'s':''} restante${x.cap-x.taken>1?'s':''}`}</span>${on?`<span class="pill p-ok">Mon créneau</span>`:`<button class="btn ${full?'btn-ghost':'btn-soft'} btn-sm" data-act="slot-pick" data-f="${f}" data-id="${x.id}" ${full?'disabled':''}>${chosen?'Changer':'Choisir'}</button>`}</div></div>`; }).join('')}</div></div></section>`; }).join('')}
  <div class="grid g-2x">
    ${panel('Réserver une séance individuelle', `${fs.length>1?`<div class="chips mb-3">${fs.map(f=>`<button class="chip-filter ${rf===f?'on':''}" data-act="rdv-f" data-f="${f}">${esc(F[f].name)}</button>`).join('')}</div>`:''}
      <div class="small-caps mb-2">Jour</div><div class="day-pick mb-3">${days.map(d=>`<button class="${rd===d?'on':''}" data-act="rdv-d" data-d="${d}"><span>${fmtD(rdvDay(d),{weekday:'short'})}</span><b>${rdvDay(d).getDate()}</b></button>`).join('')}</div>
      <div class="small-caps mb-2">Heure (45 min avec ${esc(F[rf].trainer)})</div><div class="time-pick mb-3">${RDV_TIMES.map(t=>{ const ok = rdvFree(rf,rd,t); return `<button class="${S.ui.rdvT===t?'on':''}" data-act="rdv-t" data-t="${t}" ${ok?'':'disabled'}>${t}</button>`; }).join('')}</div>
      <form data-submit="rdv-book" class="row g-2" novalidate><div class="col-sm-6"><label class="form-label" for="rdv-m">Motif</label><select class="form-select" id="rdv-m"><option>Aide sur un travail</option><option>Révision d'un module</option><option>Installation des logiciels</option><option>Orientation et projet</option><option>Autre</option></select></div><div class="col-sm-6"><label class="form-label" for="rdv-mode">Format</label><select class="form-select" id="rdv-mode"><option>En ligne (Google Meet)</option><option>Présentiel — Bloom Square Akwaba</option></select></div><div class="col-12 mt-3"><button class="btn btn-primary w-100" type="submit" ${S.ui.rdvT?'':'disabled'}>${S.ui.rdvT?`Réserver le ${fmtD(rdvDay(rd),{weekday:'long',day:'numeric',month:'long'})} à ${S.ui.rdvT}`:'Choisissez une heure'}</button></div></form>`)}
    ${panel('Mes rendez-vous', mine.length ? mine.map(r=>`<div class="row-item c-${r.f}">${datebox(rdvDay(r.d), r.f)}<div class="ri-main"><div class="ri-t">${esc(r.motif)}</div><div class="ri-s">${r.t} · ${esc(r.mode)} · ${esc(F[r.f].trainer)}</div></div><div class="d-flex flex-column align-items-end gap-1">${pill(r.st, r.st==='Confirmé'?'ok':'warn')}<button class="btn btn-ghost btn-sm py-0" data-act="rdv-cancel" data-id="${r.id}">Annuler</button></div></div>`).join('') : empty('Aucun rendez-vous réservé','fa-calendar-plus'), {p0:true})}
  </div>`;
});
Object.assign(ACT, {
  'slot-pick': el => { const f = el.dataset.f, prev = S.slots.find(x=>x.id===S.st.slot[f]), x = S.slots.find(y=>y.id===el.dataset.id); if (x.taken>=x.cap) return; if (prev) prev.taken--; x.taken++; S.st.slot[f] = x.id; audit('Créneau choisi', `${F[f].name} — ${x.day} ${x.h}`); rerender(); toast(`Créneau enregistré : ${x.day}, ${x.h}.`); },
  'rdv-f': el => { S.ui.rdvF = el.dataset.f; S.ui.rdvT = null; rerender(); },
  'rdv-d': el => { S.ui.rdvD = +el.dataset.d; S.ui.rdvT = null; rerender(); },
  'rdv-t': el => { S.ui.rdvT = el.dataset.t; rerender(); },
  'rdv-book': () => { const fs = vf(), f = S.ui.rdvF && fs.includes(S.ui.rdvF) ? S.ui.rdvF : fs[0], days = Array.from({length:14},(_,i)=>i+1).filter(d=>rdvDay(d).getDay()!==0).slice(0,10), d = S.ui.rdvD && days.includes(S.ui.rdvD) ? S.ui.rdvD : days[0];
    S.st.rdv.push({id:'rv'+Date.now(), f, d, t:S.ui.rdvT, motif:$('#rdv-m').value, mode:$('#rdv-mode').value, st:'En attente'}); S.ui.rdvT = null; rerender(); toast('Demande envoyée. Vous serez notifié(e) dès sa confirmation.'); },
  'rdv-cancel': el => { S.st.rdv.find(r=>r.id===el.dataset.id).st = 'Annulé'; rerender(); toast('Rendez-vous annulé.','info'); }
});

/* ----- Bien démarrer : 3 étapes pour un nouvel étudiant ----- */
const onbSteps = () => { const o = S.st.onb, fs = fl(); return [
  {k:'soft', n:1, t:'Installer les logiciels', d:(a=>a.slice(0,3).join(', ')+(a.length>3?` +${a.length-3}`:''))([...new Set(fs.flatMap(f=>SOFTWARE[f].map(x=>x[0])))]), done:o.soft, btn:`<button class="btn btn-sm ${o.soft?'btn-ghost':'btn-primary'}" data-act="onb-soft" data-onb="soft">${o.soft?'Revoir':'Télécharger'}</button>`},
  {k:'book', n:2, t: fs.includes('DG') ? "Télécharger « La carte de l'infographiste »" : 'Télécharger mon premier support', d: fs.includes('DG') ? 'Le livret de démarrage de l\'infographiste' : 'Le support du premier module', done:o.book, btn:`<button class="btn btn-sm ${o.book?'btn-ghost':'btn-primary'}" data-act="onb-book" data-onb="book">${o.book?'Revoir':'Télécharger'}</button>`},
  {k:'slot', n:3, t:'Choisir mon créneau', d:'Indiquez votre disponibilité parmi les créneaux proposés.', done: fs.every(f=>S.st.slot[f]), btn:`<button class="btn btn-sm ${fs.every(f=>S.st.slot[f])?'btn-ghost':'btn-primary'}" data-go="e-creneaux" data-onb="slot">${fs.every(f=>S.st.slot[f])?'Modifier':'Choisir'}</button>`}]; };
function onbCard(){ if (S.st.onb.hidden) return ''; const st = onbSteps(), n = st.filter(x=>x.done).length;
  return `<section class="panel onb mb-3" id="onb-card"><div class="panel-h"><h2>${n===3?'Vous êtes prêt(e) !':'Bien démarrer'}</h2><span class="sub">${n} / 3 étapes</span><div class="tools"><button class="btn btn-ghost btn-sm" data-act="tour-start"><i class="fa-regular fa-circle-question me-1"></i>Guide</button><button class="btn-close" data-act="onb-hide" aria-label="Masquer"></button></div></div>
  <div class="onb-steps">${st.map(x=>`<div class="onb-step ${x.done?'done':''}"><span class="onb-n">${x.done?'<i class="fa-solid fa-check"></i>':x.n}</span><div class="ri-main"><div class="fw-semibold">${x.t}</div><div class="small muted">${esc(x.d)}</div></div>${x.btn}</div>`).join('')}</div></section>`; }
Object.assign(ACT, {
  'onb-hide': () => { S.st.onb.hidden = true; rerender(); toast('Vous retrouverez le guide dans la recherche (Ctrl+K).','info'); },
  'onb-soft': () => openModal({title:'Étape 1 · Installer les logiciels', size:'modal-lg', body:`<p class="muted">Téléchargez puis installez les logiciels de votre formation. Une vidéo explique chaque installation dans la Web TV.</p>${fl().map(f=>`<div class="small-caps mt-3 mb-1">${esc(F[f].name)}</div>${SOFTWARE[f].map((x,i)=>`<div class="row-item px-0 c-${f}"><span class="icon-sq"><i class="fa-solid ${x[1]}"></i></span><div class="ri-main"><div class="ri-t">${x[0]}</div><div class="ri-s">${x[2]}</div></div><button class="btn btn-ghost btn-sm" data-act="tv-resume" data-id="v-${f}-start-${i}"><i class="fa-solid fa-play me-1"></i>Tutoriel</button><button class="btn btn-soft btn-sm" data-act="fake-dl" data-n="${esc(x[0])}">Télécharger</button></div>`).join('')}`).join('')}`, foot:`<button class="btn btn-primary" data-act="onb-soft-ok"><i class="fa-solid fa-check me-1"></i>J'ai installé les logiciels</button>`}),
  'onb-soft-ok': () => { S.st.onb.soft = true; closeModal(); rerender(); toast('Étape 1 terminée. Passez au support de formation.'); },
  'onb-book': () => openModal({title:'Étape 2 · Mon support de démarrage', body:fl().map(f=>`<div class="row-item px-0 c-${f}"><span class="icon-sq"><i class="fa-solid fa-book"></i></span><div class="ri-main"><div class="ri-t" style="white-space:normal">${esc(STARTER[f].t)}</div><div class="ri-s">${esc(STARTER[f].d)}</div></div><button class="btn btn-primary btn-sm" data-act="onb-dl" data-n="${STARTER[f].file}"><i class="fa-solid fa-download me-1"></i>PDF</button></div>`).join('')}),
  'onb-dl': el => { S.st.onb.book = true; toast(`Téléchargement : <b>${esc(el.dataset.n)}</b>`,'info'); closeModal(); rerender(); }
});

/* ----- Bulles d'information (visite guidée) ----- */
const TOUR = [
  {sel:['#onb-card'], t:'Bienvenue sur MY EVC', d:'Suivez ces 3 étapes pour bien démarrer votre formation.'},
  {sel:['[data-onb="soft"]'], t:'Étape 1 · Les logiciels', d:'Téléchargez et installez les logiciels de votre formation. Un tutoriel vidéo vous guide.'},
  {sel:['[data-onb="book"]'], t:'Étape 2 · Votre premier support', d:"Téléchargez « La carte de l'infographiste » ou votre support de démarrage."},
  {sel:['[data-onb="slot"]'], t:'Étape 3 · Votre créneau', d:'Choisissez votre disponibilité parmi les créneaux proposés à votre formation.'},
  {sel:['.bottom-nav a[href="#e-webtv"]','.menu a[href="#e-webtv"]'], t:'La Web TV', d:'Tous vos cours en vidéo, à regarder et revoir quand vous voulez.'},
  {sel:['.bottom-nav a[href="#e-todo"]','.menu a[href="#e-todo"]'], t:'Vos travaux', d:'Lisez le projet, cliquez « Je démarre », faites corriger votre travail en classe virtuelle WhatsApp, puis « Terminer » pour le joindre et le publier.'}];
let TOUR_I = -1;
function tourStart(){ TOUR_I = 0; tourShow(); }
function tourEnd(silent){ TOUR_I = -1; $('#tour-spot')?.remove(); $('#tour-tip')?.remove(); window.removeEventListener('resize', tourPlace); window.removeEventListener('scroll', tourPlace); }
function tourTarget(){ const st = TOUR[TOUR_I]; for (const s of st.sel) for (const el of $$(s)) { const r = el.getBoundingClientRect(); if (r.width && r.height) return el; } return null; }
function tourShow(){ const el = tourTarget(); if (!el) { if (TOUR_I < TOUR.length-1) { TOUR_I++; return tourShow(); } return tourEnd(); }
  if (!$('#tour-spot')) { const sp = document.createElement('div'); sp.id = 'tour-spot'; document.body.appendChild(sp); const tp = document.createElement('div'); tp.id = 'tour-tip'; tp.setAttribute('role','dialog'); document.body.appendChild(tp); window.addEventListener('resize', tourPlace); window.addEventListener('scroll', tourPlace, {passive:true}); }
  const st = TOUR[TOUR_I], last = TOUR_I===TOUR.length-1;
  $('#tour-tip').innerHTML = `<div class="tt-n">${TOUR_I+1} / ${TOUR.length}</div><div class="tt-t">${st.t}</div><div class="tt-d">${st.d}</div><div class="tt-a"><button class="btn btn-link btn-sm px-0 muted" data-act="tour-end">Passer</button><span class="ms-auto d-flex gap-2">${TOUR_I?`<button class="btn btn-ghost btn-sm" data-act="tour-prev">Précédent</button>`:''}<button class="btn btn-primary btn-sm" data-act="tour-next">${last?'Terminer':'Suivant'}</button></span></div>`;
  const r = el.getBoundingClientRect(); if (r.top < 70 || r.bottom > innerHeight-90) el.scrollIntoView({block:'center'}); tourPlace(); $('#tour-tip [data-act=tour-next]')?.focus(); }
function tourPlace(){ if (TOUR_I<0) return; const el = tourTarget(), sp = $('#tour-spot'), tp = $('#tour-tip'); if (!el || !sp) return; const r = el.getBoundingClientRect(), pad = 6;
  Object.assign(sp.style, {top:r.top-pad+'px', left:r.left-pad+'px', width:r.width+pad*2+'px', height:r.height+pad*2+'px'});
  const tw = Math.min(320, innerWidth-24), th = tp.offsetHeight, below = r.bottom + 14 + th < innerHeight;
  tp.style.width = tw+'px'; tp.style.left = Math.max(12, Math.min(innerWidth-tw-12, r.left + r.width/2 - tw/2))+'px'; tp.style.top = (below ? r.bottom+14 : Math.max(12, r.top-14-th))+'px';
  tp.dataset.pos = below ? 'below' : 'above'; tp.style.setProperty('--ax', Math.max(16, Math.min(tw-16, r.left + r.width/2 - parseFloat(tp.style.left)))+'px'); }
Object.assign(ACT, { 'tour-start': () => tourStart(), 'tour-next': () => { if (TOUR_I>=TOUR.length-1) { tourEnd(); toast('Bonne formation sur MY EVC !'); } else { TOUR_I++; tourShow(); } }, 'tour-prev': () => { TOUR_I = Math.max(0, TOUR_I-1); tourShow(); }, 'tour-end': () => tourEnd() });
document.addEventListener('keydown', e => { if (e.key==='Escape' && TOUR_I>=0) tourEnd(); });
